(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-feature-cache-rescue"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-1\">一 · 一次“缓存命中”引发的线上画质事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-2\">二 · 算法解决的问题域：逐 block 的复用决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-3\">三 · 它不解决什么：三条明确的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-4\">四 · 失败模式：三种可复现的工程故障</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-5\">五 · 适用边界的判定方法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-6\">六 · 失效边界：阈值、图捕获与显存预算的三重夹击</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-7\">七 · 入口：缓存键的生成与相似度判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-8\">八 · 复用路径：读缓存代替前向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-9\">九 · 救援队列：标记、排序与重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-10\">十 · 残差修正与缓存写回</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-11\">十一 · 汇聚与 scheduler 交接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-12\">十二 · 端到端代价账与分支规整化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-13\">十三 · 相似度门控的失效边界与分支代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-14\">十四 · 逐项拆解：reuse 指示函数与单步时延的加和结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-15\">十五 · 相似度公式的数值细节：键的选择与余弦的尺度不变性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-16\">十六 · 救援队列与残差修正：从判定到写回的可实现伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-17\">十七 · 显存账：缓存占用如何挤压 batch 容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-18\">十八 · 阈值标定与失败模式的量化定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-19\">十九 · 边界、失效条件与系统代价：这套缓存方案在什么情况下会反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-20\">二十 · 请求形态：什么样的采样轨迹才吃得到复用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-21\">二十一 · 并发与批大小：缓存显存是第一约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-22\">二十二 · 负载不对时的三种崩塌</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-23\">二十三 · 配方判据：把请求分流的可执行规则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-24\">二十四 · 与相邻路径的负载边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-25\">二十五 · 负载配方：什么样的请求才配得上这套缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-26\">二十六 · 硬件档位：按缓存驻留量反推 SM 与显存档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-27\">二十七 · 并行拓扑：把分支收敛在卡内，把救援留在本地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-28\">二十八 · 量化方案：计算精度与缓存精度分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-29\">二十九 · KV 策略与显存预算：缓存、KV、激活三方分池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-30\">三十 · 调度参数：阈值、救援率与 CUDA Graph 分段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-31\">三十一 · 可复现配置思路：从预算不等式倒推参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-32\">三十二 · 部署配方的失效边界：从阈值到显存预算的三条断裂线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-33\">三十三 · 显存账本：缓存是第二套激活</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-34\">三十四 · 带宽与分支：规整性被打破的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-35\">三十五 · 通信：救援队列是集合通信的扰动源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-36\">三十六 · 功耗与频率：省下的算力不等于省下的瓦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-37\">三十七 · 尾延迟：阈值与规模的非线性耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-38\">三十八 · 规模放大后先崩的是显存预算，不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-39\">三十九 · 精度失败：阈值漏救援与漂移的传播路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-40\">四十 · 显存失败：缓存预算与 batch 容量的零和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-41\">四十一 · 执行失败：分支破坏 kernel 规整性与 CUDA Graph 断裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-42\">四十二 · 调度失败：批抖动、路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-43\">四十三 · 监控面：把三个失败域压到一张面板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-44\">四十四 · 回滚路径：分级降级而非一刀切关闭</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-45\">四十五 · 对照轴：三条改动路径的坐标系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-46\">四十六 · 决策表：五类场景的选型与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-47\">四十七 · 选型判据的形式化：收益与约束的不等式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-48\">四十八 · 具体例子：一次选型推演</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-49\">四十九 · 与量化、注意力的交叉约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-50\">五十 · 适用条件的硬边界与选型收口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-feature-cache-rescue-sec-51\">五十一 · 与固定间隔缓存、步数蒸馏的选型边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:505px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 504.9 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">step t 开始时，对每个 DiT block 计算输入与缓存键的余弦相…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">相似度超阈的 block 跳过前向，直接读取上一步输出缓存</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">相似度低的 block 标记为救援对象，进入重算队列</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">重算 block 的输出与缓存做残差修正，写回缓存供下一步复用</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">全部 block 汇聚后进入 scheduler 更新 latent</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-feature-cache-rescue-sec-1\">一 · 一次“缓存命中”引发的线上画质事故</h3>\n<p>某条多步扩散采样服务在压测后上线了固定间隔缓存：每隔一步复用上一步全部 DiT block 的输出，单步时延立刻掉下来，容量规划也按这个收益做了。事故出现在一次带强语义切换的请求上——提示词从“金属质感的机械臂”切到“暖光下的木质桌面”，采样轨迹在中段发生剧烈转向，而固定间隔缓存对这一转向毫无感知：被复用的 block 输出直接汇入 scheduler 更新 latent，画面在切换处出现局部结构漂移，跨 step 一致性下降，肉眼可见的是物体边缘“粘”在前一语义的几何上。更糟的是，这类请求在分桶里占比不高，监控上的平均单步时延很漂亮，画质问题只在少数请求上暴露，排查时被误判为采样器噪声。这就是本算法要解决的具体推理问题：不是“缓存有没有用”，而是“缓存凭什么知道自己此刻不该复用”。固定间隔缓存把复用决策交给了 step 周期的先验，而不是数据本身；一旦语义切换稀疏但剧烈，先验就失效。</p>\n<p>事故的工程代价可以量化到三个维度：单步时延的收益被返工抵消（重放请求、人工复核）、显存预算被缓存挤占（高分辨率大 DiT 下缓存与 KV/激活争抢，batch 容量受限）、以及 SLO 层面的隐性违约——平均时延达标但尾部请求的画质一致性不达标。这三者共同构成了“盲目缓存”的代价结构：收益是确定的，风险是不确定的，而不确定性恰好落在最难监控的语义切换点上。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-2\">二 · 算法解决的问题域：逐 block 的复用决策</h3>\n<p>该算法把复用决策从 step 级下放到 block 级，用数据相似度替代周期先验。step t 开始时，对每个 DiT block 计算其输入与缓存键的余弦相似度：</p>\n<div class=\"formula\">$$s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})=\\frac{\\mathbf{k}_i^{t}\\cdot\\mathbf{k}_i^{t-1}}{\\lVert\\mathbf{k}_i^{t}\\rVert\\,\\lVert\\mathbf{k}_i^{t-1}\\rVert}$$</div>\n<p>其中 $\\mathbf{k}_i^{t}$ 为第 $i$ 个 block 在第 $t$ 步的缓存键。当 $s_i&gt;\\tau$ 时复用缓存、跳过该 block 前向；否则该 block 进入救援队列重算，重算输出与缓存做残差修正后写回缓存，供下一步复用；全部 block 汇聚后进入 scheduler 更新 latent。复用判定的整体形式可写成：</p>\n<div class=\"formula\">$$\\text{reuse}_\\ell = \\mathbb{1}\\left[\\cos(h_\\ell^t, h_\\ell^{t-1}) &gt; \\tau\\right],\\quad T_{\\text{step}} \\approx \\sum_{\\ell} \\left(1-\\text{reuse}_\\ell\\right) T_\\ell + T_{\\text{cache}}$$</div>\n<p>这个式子说明了收益的来源与上限：单步时延由未被复用的 block 前向时间加上缓存读取开销构成，复用率越高收益越大，但 $T_{\\text{cache}}$ 与判定开销是固定成本，复用率低时反而亏。它解决的问题边界由此清晰——相邻 step 输出相似度高、语义切换稀疏的多步扩散采样，在不重训练的前提下降低单步时延；材料给出的收益区间是单步时延降 20%–40%，超出该范围的收益材料未给出。</p>\n<p>具体例子：一个 24 block 的 DiT，在某步中 18 个 block 的 $s_i$ 超过阈值被复用，6 个 block 因语义切换被标记救援并重算。若单 block 前向时间为 $T_\\ell$，则该步计算量约为全量的四分之一，加上判定与缓存读取的固定开销，落到端到端单步时延上就是材料所述区间内的收益。关键在于这 6 个 block 是被数据选出来的，而不是被周期猜出来的。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-3\">三 · 它不解决什么：三条明确的边界</h3>\n<p>第一，它不改变采样轨迹与步数。步数蒸馏与一致性模型通过改变采样轨迹、压缩步数来提速，属于另一条技术路线；本算法不重训练、只改单步内的计算路径，因此对“步数本身太多”的问题无能为力——若采样器仍需 30 步，它只能在每步内部省，不能把 30 步变成 8 步。第二，它不解决跨请求的批调度问题。缓存是 per-request、per-step 的状态，批内不同请求的救援 block 集合不同，分支发散会破坏 kernel 规整性，这属于批调度与 CUDA Graph 捕获的工程问题，算法本身不提供批内合并策略。第三，它不保证语义切换处的绝对正确。动态救援把漂移限制在局部 block，使画质退化小于固定间隔缓存，但阈值设置不当仍会在切换处漏救援；它降低的是漂移的范围与概率，不是消除漂移。</p>\n<p>还有一条隐性边界：规模上限受缓存显存约束。高分辨率大 DiT 下缓存与 KV/激活争抢显存预算，batch 容量受限，吞吐可能不升反降。这意味着该算法的适用规模不是“越大越好”，而是要在显存预算内做权衡——当缓存占用把 batch 从 N 压到 N/2 时，单步时延的 20%–40% 收益未必能换算成吞吐收益。工程判断应落在“该分辨率档位下缓存占用是否挤占关键预算”这一具体问题上，而不是笼统地认为缓存总是划算。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-4\">四 · 失败模式：三种可复现的工程故障</h3>\n<p>失败模式一，阈值过松导致漏救援。$\\tau$ 设得过低时，语义切换处本应重算的 block 被判为可复用，缓存输出直接进入 scheduler，造成画面局部漂移与跨 step 一致性下降。这类故障在监控上表现为平均指标正常、尾部画质异常，排查成本高。失败模式二，分支破坏 kernel 规整性。相似度判定与救援调度引入数据相关的分支，若未做 CUDA Graph 分段捕获，会出现捕获失败或重放错误，单步时延收益被抵消——这是纯工程故障，与画质无关，但同样致命。失败模式三，缓存显存挤占。高分辨率大 DiT 下缓存与 KV/激活争抢显存预算，batch 容量下降，吞吐不升反降。</p>\n<p>三种失败模式共享一个结构：它们都不是算法数学层面的错误，而是判定阈值、执行图捕获、显存预算这三个工程旋钮没调好。具体例子：某分桶内 batch 容量因缓存占用从 8 降到 4，单步时延虽降 30%，但吞吐减半，SLO 以单步时延为目标时看似达标，以吞吐为目标时则违约。这说明该算法的部署配方必须把缓存占用与 KV/激活统一规划进显存预算，而不是把缓存当作“免费”的加速手段。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-5\">五 · 适用边界的判定方法</h3>\n<p>判断一个扩散推理负载是否适用，应看三个可测信号：相邻 step 的 block 输出相似度分布是否集中在高相似区间（决定复用率上限）、语义切换在采样轨迹上是否稀疏（决定救援队列的规模与分支发散程度）、以及目标分辨率下缓存占用是否挤占 KV/激活预算（决定 batch 容量是否受损）。三者中任一不满足，收益就会从材料给出的 20%–40% 区间滑出，而材料未给出该区间之外的收益数据，因此不应外推。</p>\n<p>与相邻算法的差别也划定了边界：区别于固定间隔缓存（按固定 step 周期复用、不检测相似度），本算法逐 block 检测相似度并引入救援队列只重算差异 block；区别于步数蒸馏与一致性模型，它不重训练、只改单步内计算路径。因此它适合“轨迹不变、步数不变、只想在单步内省算力”的场景，不适合“需要改变采样轨迹或压缩步数”的场景。判定时应先确认采样器与步数是否已冻结，再评估相似度分布与显存预算，最后才谈收益区间。</p>\n<p>工程判断落在一个具体机制上：把 $\\tau$ 与救援队列的触发条件做成按分辨率与步数分桶的可调参数，而不是全局常量；同时用 CUDA Graph 分段捕获把“判定—复用—救援—残差修正”切成规整段，使分支发散被限制在段边界内。这两件事决定了该算法能否在真实服务里稳定拿到那 20%–40%，而不是在压测里拿到、在线上还回去。</p>\n\n\n<h3 id=\"alg-feature-cache-rescue-sec-6\">六 · 失效边界：阈值、图捕获与显存预算的三重夹击</h3>\n<p>这套算法的适用面比宣传口径窄得多。它成立的前提是“相邻 step 的 DiT block 输出高度相似、语义切换稀疏”，而扩散采样恰恰在几个位置天然违反这个前提：采样前段 latent 从纯噪声快速成形、文本条件切换或 CFG 引导强度调整的那几步、以及高噪声区间向低噪声区间过渡的转折点。在这些位置，block 输出的余弦相似度会整体塌陷，若阈值 τ 设得过松，救援队列几乎为空，缓存输出被直接送进 scheduler 更新 latent，画面出现局部结构漂移——单帧看是细节糊化，跨 step 看是同一物体在相邻帧间位置抖动，一致性损失比固定间隔缓存更隐蔽也更难调。反过来把 τ 收紧，救援队列膨胀，跳过率下降，单步时延收益从材料给出的 20%–40% 迅速回落到接近全量重算，还要额外付出相似度判定本身的开销。阈值不是超参，是这套方案的能力开关。</p>\n<p>第二个失效条件在执行层。复用判定与救援调度本质上是数据相关的分支：同一个 kernel 在不同 step、不同 block 上走不同路径，规整性被打破。若不做 CUDA Graph 分段捕获，捕获阶段遇到分支就会失败或重放错误，收益被抵消；即便做了分段捕获，段与段之间的边界也把原本可以融合的算子切开，引入额外的启动与同步开销。更麻烦的是救援队列的长度随 step 动态变化，分段捕获的段数若按最坏情况静态分配，空转段照样消耗调度时间；若按典型情况分配，语义切换处就会溢出到图外执行，把这条路径的时延尖峰暴露给 SLO。工程上必须把“判定—救援—残差修正”三段拆成独立可捕获单元，并让救援段的批形状按桶对齐，否则分支带来的不是节省而是抖动。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\sum_{\\ell} \\left(1-\\text{reuse}_\\ell\\right) T_\\ell + T_{\\text{cache}} + T_{\\text{branch}}$$</div>\n<p>第三个失效条件是显存。缓存按 block 保存上一步输出，占用随 DiT 深度与分辨率线性上升；在高分辨率大 DiT 场景下，它与 KV cache、激活峰值争抢同一份预算，直接压缩 batch 容量。设单请求缓存占用为 $M_c$、每请求 KV 与激活为 $M_a$，则可用 batch 上限近似为 $B \\le \\lfloor (M_{\\text{free}} - M_{\\text{reserve}})/(M_c + M_a) \\rfloor$。当 $M_c$ 与 $M_a$ 同量级时，batch 容量近乎腰斩，单步时延的百分比收益被吞吐的绝对损失吞掉——这是最典型的“延迟降了、吞吐没升反降”的翻车形态。一个具体例子：某条多步采样服务在分辨率提升一档后，缓存占用把 batch 从可接受档位压到个位数，单步时延确实降了两成，但每秒出图数反而下降，SLO 从时延指标切换到吞吐指标后整条路径失效。因此部署前必须先做显存预算的统一规划，把缓存当作与 KV 平级的容量项，而不是“顺带存一下”。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发场景</th><th>系统代价</th></tr></thead><tbody><tr><td>τ 过松</td><td>语义切换、CFG 调整步</td><td>局部漂移、跨 step 一致性下降</td></tr><tr><td>分支未分段捕获</td><td>救援队列动态长度</td><td>捕获失败/重放错误、时延抖动</td></tr><tr><td>缓存挤占显存</td><td>高分辨率大 DiT</td><td>batch 容量下降、吞吐不升反降</td></tr></tbody></table>\n<p>它明确不解决的问题也要说清：不改采样轨迹、不减步数，因此对“总步数太多”这一根本成本无能为力，那是步数蒸馏与一致性模型的地盘；不做跨请求复用，缓存只在单请求的相邻 step 间有效，对高并发小 batch 场景几乎无收益；也不解决量化与数值精度问题，NVFP4/FP8 下的相似度判定本身会受量化噪声影响，τ 需要在量化后的键上重新标定。真正适合它的负载是：多步采样、分辨率中等、语义切换集中在少数已知 step、且显存预算能同时容纳缓存与 KV 的批式服务。超出这个边界，收益材料未给出，工程判断应当是先关掉它而不是调参硬撑。</p>\n<h3 id=\"alg-feature-cache-rescue-sec-7\">七 · 入口：缓存键的生成与相似度判定</h3>\n<p>救援机制的第一步不是“跳过”，而是“判定”。每个 DiT block 在 step t 的入口处，需要拿到两个量：当前步该 block 的输入投影所导出的缓存键 <strong>k<sub>i</sub><sup>t</sup></strong>，以及上一步写回缓存的键 <strong>k<sub>i</sub><sup>t-1</sup></strong>。键不是 block 的完整输出，而是从输入激活中抽取的低维指纹——通常是 block 输入经一次轻量线性投影或对通道做池化后得到的定长向量。选择“输入键”而非“输出键”是关键工程判断：输出键要等前向算完才有，判定就失去提前跳过的意义；输入键在 block 前向之前即可获得，判定与计算可以解耦。</p>\n<p>判定本身是一次余弦相似度：</p>\n<div class=\"formula\">$$s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})=\\frac{\\mathbf{k}_i^{t}\\cdot\\mathbf{k}_i^{t-1}}{\\lVert\\mathbf{k}_i^{t}\\rVert\\,\\lVert\\mathbf{k}_i^{t-1}\\rVert}$$</div>\n<p>输入是两组定长向量，输出是一个标量 s<sub>i</sub> 与一个布尔决策：s<sub>i</sub> &gt; τ 则复用，否则入救援队列。代价分两块：算力上是每 block 一次点积加两次范数，相对该 block 的注意力与 GEMM 可忽略；真正昂贵的是<strong>规整性代价</strong>——判定把原本一条直线的前向切成“判定—分支—计算/读取”三段，GPU 上同一 warp 组可能走向不同路径，分支发散使 SM 占用率下降。因此判定必须做成极小的独立 kernel 或融合进前置的 norm/projection 中，把标量结果写入一个 device 侧决策数组，供后续分段调度读取，而不是在 block 内部用 if 原地分叉。</p>\n<p>具体例子：一个 28 层 DiT，每层 2 个 block 共 56 个判定点。若 τ 取偏松值，第 12 步语义从“构图”切到“细化”时，前 20 个 block 的输入键变化仍低于阈值而被判复用，救援队列几乎为空——这正是失败模式里“漏救援”的入口，漂移会一路带到 scheduler。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-8\">八 · 复用路径：读缓存代替前向</h3>\n<p>被判复用的 block 走最短路径：不执行 QKV 投影、注意力、FFN，直接从特征缓存中按 (block_id, step-1) 索引取出上一步的输出张量，作为本步该 block 的输出向下游传递。输入是决策数组中的 reuse 标记与缓存句柄，输出是一块与 block 输出同形状的激活，代价从 T<sub>ℓ</sub>（该 block 完整前向时延）降为 T<sub>cache</sub>（一次显存读）。</p>\n<p>这条路径的瓶颈从算力切换到<strong>显存带宽</strong>。DiT block 输出激活的体量随分辨率线性上升：高分辨率下单个 block 输出可达数 MB 级，56 个 block 全复用意味着每步要搬运上百 MB 的激活，HBM 带宽成为新的时延下限。这也解释了为什么复用收益存在上限——当 T<sub>cache</sub> 逼近 T<sub>ℓ</sub> 时，跳过计算不再划算。工程上应对手段是缓存分层：把高频复用的浅层 block 输出留在片上或 L2 友好的布局中，深层 block 输出放 HBM，并按 block 重要性做差异化保留。</p>\n<p>单步时延的账可以写成：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\sum_{\\ell} \\left(1-\\text{reuse}_\\ell\\right) T_\\ell + T_{\\text{cache}}$$</div>\n<p>材料给出的整体收益是单步时延降 20%–40%，这个区间对应的正是“复用比例 × 单 block 前向占比”与“缓存读取开销”之间的净差。复用比例偏低则收益趋近于零，偏高则 T<sub>cache</sub> 项抬头，收益被吃掉。具体例子：若某步 56 个 block 中 40 个复用、16 个重算，且单 block 前向占单步时延的主要部分，则理论时延约为原值的四成加上缓存搬运项，落在材料区间内；但若缓存布局导致读取跨 NUMA 或未对齐，T<sub>cache</sub> 抬升会把净收益压到区间下沿。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-9\">九 · 救援队列：标记、排序与重算</h3>\n<p>相似度低于 τ 的 block 被写入救援队列。队列元素至少包含 block_id、当前步输入句柄、缓存句柄与相似度分值。输入是判定阶段的决策数组，输出是一个待重算的 block 列表。这一步的代价主要是<strong>调度开销</strong>：队列在 device 侧还是 host 侧决定了下游能否保持异步。放 host 侧会引入同步点，破坏流水；放 device 侧则需要一个紧凑的索引压缩（stream compaction）把稀疏的救援标记压成连续列表，供后续 kernel 按列表长度启动，避免为全部 56 个 block 启动 kernel 却只算 16 个的浪费。</p>\n<p>排序策略影响救援质量。按相似度升序重算，优先处理差异最大的 block，可以让残差修正更早收敛；按 block 深度排序则利于访存局部性。工程上通常两者折中：先按深度分桶，桶内按相似度排序，使重算 kernel 的输入激活尽量连续。</p>\n<p>重算路径执行的是标准 block 前向，输入是当前步的真实激活，输出是新算出的 block 输出 h<sub>ℓ</sub><sup>t</sup>。代价即 T<sub>ℓ</sub>，与复用路径的 T<sub>cache</sub> 形成对比。具体例子：语义切换步上救援队列可能从常态的个位数膨胀到二三十个 block，此时单步时延接近全量重算，救援机制退化为“选择性全算”——这不是故障，而是设计上的安全阀：宁可这一步慢，也不让漂移进入 scheduler。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-10\">十 · 残差修正与缓存写回</h3>\n<p>重算输出不能直接替换缓存，否则相邻 step 之间的特征会因“重算块与复用块来自不同步”而出现接缝。修正步骤把新算输出与旧缓存做残差融合：</p>\n<div class=\"formula\">$$h_\\ell^{t}\\leftarrow h_\\ell^{t}+\\alpha\\left(h_\\ell^{t}-h_\\ell^{t-1}\\right)$$</div>\n<p>其中 α 为修正系数，控制新信息注入的比例。输入是新算输出与上一步缓存，输出是写回缓存的融合特征。这一步的代价是每救援 block 一次逐元素读写，量级与激活体量同阶，属带宽开销而非算力开销。α 取 1 等价于完全信任重算，取 0 等价于忽略救援——两者都会破坏一致性，实践中 α 随相似度分值自适应：相似度越低，α 越接近 1。</p>\n<p>写回动作把融合结果按 (block_id, t) 写入缓存，供 step t+1 的判定读取。这里有一个隐式代价：缓存写入与下一步的判定读取构成 RAW 依赖，若不做双缓冲，写回会阻塞下一步的判定 kernel 启动。双缓冲把缓存分成奇偶两份，写回与读取交错，代价是显存占用翻倍——这正是缓存容量约束的来源之一。</p>\n<p>具体例子：某救援 block 的新算输出与旧缓存差异集中在少数通道上，逐元素融合后接缝被压平；若跳过修正直接替换，下一步该 block 的输入键会因突变而被判为低相似度，触发连锁救援，救援队列雪崩，单步时延收益被完全抵消。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-11\">十一 · 汇聚与 scheduler 交接</h3>\n<p>全部 block 处理完毕后，各 block 输出按深度顺序汇聚成完整 latent 更新所需的特征张量，交给 scheduler 执行 latent 更新。输入是复用块（读缓存）与救援块（重算加修正）的混合输出，输出是更新后的 latent。这一步的代价是<strong>同步代价</strong>：汇聚点是一个天然的 barrier，复用路径与重算路径在此必须全部完成。若两条路径时延差异大，barrier 会让快路径空等慢路径，SM 利用率在汇聚前出现塌陷。</p>\n<p>缓解手段是把汇聚做成流水：按 block 深度分段，浅层汇聚完即可启动 scheduler 的部分更新，深层 block 与下一步的判定重叠。但这要求 CUDA Graph 分段捕获——材料明确指出分支破坏 kernel 规整性，需分段捕获以维持执行效率。分段粒度是工程权衡：段太细，图捕获节点爆炸、启动开销上升；段太粗，barrier 空等回归。经验上以“判定段—复用段—救援段—汇聚段”四段为基线，救援段按队列长度动态细分。</p>\n<p>具体例子：一个 batch 内不同请求处于不同采样步，语义切换步不一致，救援队列长度在请求间差异极大。若按 batch 统一分段，短队列请求会被长队列请求拖住；按请求分桶、桶内共享图捕获，是维持 batch 容量与单步时延平衡的常见做法。这里的容量约束直接来自缓存显存：高分辨率大 DiT 下缓存与 KV/激活争抢显存预算，batch 容量受限，吞吐不升反降是必须监控的失败模式。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-12\">十二 · 端到端代价账与分支规整化</h3>\n<p>把五步的代价串起来，单步时延由四部分构成：判定开销（每 block 一次点积，可忽略但引入分支）、复用读取（带宽主导）、救援重算（算力主导）、修正与汇聚（带宽加 barrier）。收益能否落在 20%–40% 区间，取决于复用比例与缓存读取效率的乘积是否压过分支与 barrier 的固定开销。</p>\n<p>分支规整化是这条链上最容易被低估的工程点。判定产生的布尔数组若直接驱动 block 内的条件执行，warp 发散会让复用块的“空转”仍然占用 SM 周期；正确做法是把决策数组作为数据传给分段 kernel，用“按列表启动”替代“按条件跳过”，让复用块根本不进入计算 kernel。这样分支代价从执行期转移到调度期，CUDA Graph 分段捕获才有意义。伪代码思路是：判定 kernel 输出决策数组 → compaction 输出救援索引 → 复用 kernel 按全 block 索引批量读缓存 → 救援 kernel 按救援索引启动 → 修正 kernel 按救援索引写回 → 汇聚 kernel 合并。每个 kernel 的启动形状由数据决定，而非由 if 决定。</p>\n<p>最终判断落在阈值 τ 与缓存预算的联合整定上：τ 偏松省算力但漏救援，τ 偏紧救援队列膨胀使单步时延趋近全量重算；缓存预算决定能保留多少 block 输出，进而决定复用比例的上限。两者必须与 batch 容量一起规划，因为缓存挤占显存会直接压低并发请求数，把单步时延的收益从吞吐维度上抵消掉。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-13\">十三 · 相似度门控的失效边界与分支代价</h3>\n<p>这套机制真正的工程难点不在“跳过”，而在“判断跳过”这一步本身。step t 开始时对每个 DiT block 计算 <span class=\"inline-formula\">s_i=cos(k_i^t,k_i^{t-1})</span>，这一步的输入是当前 block 的缓存键与上一步写回的键，输出是一个布尔复用标志与一个救援队列成员标记；代价上，它是一次逐 block 的向量归约，规模虽小却串在关键路径上，且必须在所有 block 前向之前完成，等于给每个 step 增加了一段不可与主计算重叠的前置延迟。阈值 τ 是唯一旋钮：τ 偏松时，语义切换处（如从构图转入细节刻画）的 block 输出差异被误判为相似，缓存直接进入 scheduler，局部漂移与跨 step 一致性下降同时出现；τ 偏紧则救援队列膨胀，复用率塌缩，单步时延回落到全量重算水平，20%–40% 的收益被吃掉。</p>\n<p>救援路径的代价是结构性的：被标记的 block 进入重算队列，其输出与缓存做残差修正后写回，这使一个 step 内同时存在“读缓存”和“跑前向”两类 block，执行流从规整的整网前向退化为按 block 分段的条件执行。kernel 规整性被破坏的直接后果是 CUDA Graph 无法整图捕获，必须按复用/救援的划分做分段捕获与重放；若分段边界与运行时实际分支不匹配，会出现捕获失败或重放错误，此时收益不仅归零，还要额外付出重放开销。工程上应把相似度判定与救援调度放在图外做控制决策，只把确定性的前向段纳入图内。</p>\n<p>显存是第二个硬边界。缓存需为每个 block 保留上一步输出，高分辨率大 DiT 下这部分占用与 KV、激活争抢同一预算，batch 容量因此受限——单步时延下降但并发批数减少，吞吐可能不升反降。可用的粗算判据是：只有当单步节省的算力时间超过判定与分段调度引入的固定开销时，收益才成立，即 <span class=\"inline-formula\">Σ_ℓ reuse_ℓ·T_ℓ &gt; T_cache + T_branch</span>；其中 T_branch 随 block 数与分段数增长，T_cache 随缓存精度与分辨率增长。适用边界因此很窄：相邻 step 输出相似度高、语义切换稀疏的多步采样，且分辨率与 DiT 规模使缓存占用仍留有余量；语义切换频繁或 batch 已逼近显存上限时，应退回固定间隔缓存或全量重算。</p>\n<h3 id=\"alg-feature-cache-rescue-sec-14\">十四 · 逐项拆解：reuse 指示函数与单步时延的加和结构</h3>\n<p>核心式只有两项，但每一项都藏着工程取舍。第一项 <span class=\"formula\">$$\\text{reuse}_\\ell = \\mathbb{1}\\left[\\cos(h_\\ell^t, h_\\ell^{t-1}) &gt; \\tau\\right]$$</span> 是一个指示函数，输出 0/1，决定第 <span>ℓ</span> 个 DiT block 在这一步是否走缓存路径。它把“是否跳过”从连续打分压成二值决策，好处是分支清晰、便于按 block 组织重算队列；代价是阈值 <span>τ</span> 附近没有缓冲带，相似度 0.501 与 0.499 走向完全不同的执行路径。第二项 <span class=\"formula\">$$T_{\\text{step}} \\approx \\sum_{\\ell} \\left(1-\\text{reuse}_\\ell\\right) T_\\ell + T_{\\text{cache}}$$</span> 把单步时延写成“被救援 block 的前向时间之和 + 缓存路径开销”。注意 <span>T_cache</span> 不是常数项而是与复用 block 数正相关的量：读缓存、做残差修正、写回缓存都要花时间，只是远小于一次完整前向。</p>\n<p>推导的关键一步在于把 <span>T_cache</span> 拆成三段：缓存读取 <span>T_read</span>、残差修正 <span>T_res</span>、缓存写回 <span>T_write</span>。设复用 block 数为 <span>R</span>、救援 block 数为 <span>M</span>、总 block 数 <span>L=R+M</span>，则 <span class=\"formula\">$$T_{\\text{cache}} \\approx R\\cdot T_{\\text{read}} + M\\cdot T_{\\text{res}} + R\\cdot T_{\\text{write}}$$</span> 这一步的意义是：收益并不随 <span>R</span> 线性增长，因为 <span>T_write</span> 与 <span>R</span> 同向增长。只有当 <span>T_read + T_write ≪ T_ℓ</span> 时，跳过才有净收益。对 Blackwell 上的大 DiT block，一次完整前向包含 tcgen05 MMA、TMEM 往返与激活搬运，<span>T_ℓ</span> 的量级远大于一次 HBM 读加一次写，所以净收益成立；但若 block 很小、或缓存放在远端显存，这个不等式会被打破。</p>\n<p>代入可得单步时延的相对收益：<span class=\"formula\">$$\\frac{\\Delta T_{\\text{step}}}{T_{\\text{step}}} \\approx \\frac{\\sum_\\ell \\text{reuse}_\\ell\\,(T_\\ell - T_{\\text{read}} - T_{\\text{write}}) - M\\cdot T_{\\text{res}}}{\\sum_\\ell T_\\ell}$$</span> 分子里每一项都是“省下的前向时间减去缓存路径成本”。材料给出的单步时延降幅 20%–40%，对应的正是分子为正且 <span>R/L</span> 落在中高区间的工况。工程判断因此很直接：先测单个 block 的 <span>T_ℓ</span> 与 <span>T_read+T_write</span> 之比，比值小于某个门槛时，这套机制在该模型上不划算，应退回固定间隔缓存或不做缓存。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-15\">十五 · 相似度公式的数值细节：键的选择与余弦的尺度不变性</h3>\n<p>判定式用的是缓存键 <span>k_i^t</span> 而非 block 输出本身：<span class=\"formula\">$$s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})=\\frac{\\mathbf{k}_i^{t}\\cdot\\mathbf{k}_i^{t-1}}{\\lVert\\mathbf{k}_i^{t}\\rVert\\,\\lVert\\mathbf{k}_i^{t-1}\\rVert}$$</span> 余弦的尺度不变性在这里是双刃剑。好处是 latent 的整体幅值漂移（例如 scheduler 更新后 latent 被缩放）不会误触发救援；坏处是当语义发生切换、但特征方向恰好接近时，余弦仍然很高，漏救援。这就是失败模式里“阈值过松在语义切换处漏掉救援”的数值根源——余弦只看向量夹角，不看模长变化，而扩散采样中的语义切换往往伴随幅值重分布。</p>\n<p>因此键的构造要选在“方向敏感、幅值不敏感”的位置之外做补偿。常见做法是把键取在 block 归一化之后的激活上，并在判定时附加一个模长比检查：<span class=\"formula\">$$\\text{rescue}_i = \\mathbb{1}\\left[s_i \\le \\tau \\;\\lor\\; \\frac{\\lVert\\mathbf{k}_i^{t}\\rVert}{\\lVert\\mathbf{k}_i^{t-1}\\rVert} \\notin [1/\\rho, \\rho]\\right]$$</span> 其中 <span>ρ</span> 是模长容忍带。这一项不改变主公式的结构，只是把“方向像但幅值跳变”的情况拉进救援队列。代价是每 block 多一次范数计算与一次比较，属于寄存器级开销，相对 <span>T_ℓ</span> 可忽略；但它让阈值 <span>τ</span> 可以设得更松，从而保住复用率。</p>\n<p>另一个数值细节是相似度计算的精度。若键以 FP8 存储以省显存，余弦点积会在低精度下累积误差，<span>τ</span> 附近的判定抖动会放大成执行路径抖动，进而让 CUDA Graph 的分段边界不稳定。稳妥做法是键用 BF16 或 FP16 保存、点积在 FP32 下累加，仅缓存输出本身用低精度。显存代价是键占 <span>2 bytes × hidden × L</span> 量级，相对整块输出缓存是小头；带宽代价是每步每 block 一次键读取，属于 <span>T_read</span> 的一部分，已计入上面的加和式。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-16\">十六 · 救援队列与残差修正：从判定到写回的可实现伪代码</h3>\n<p>把公式落到可执行路径，关键是让“判定—入队—重算—修正—写回”五步在同一个 step 内闭合，且不破坏 kernel 规整性。伪代码思路如下（以 block 为粒度，<span>cache</span> 为按 block 索引的上一步输出）：</p>\n<ul>\n<li>对每个 block <span>i</span>：读 <span>k_i^t</span>，与 <span>k_i^{t-1}</span> 做 FP32 累加的点积与范数，得 <span>s_i</span>；同时算模长比，按上式得 <span>rescue_i</span>。</li>\n<li>若 <span>rescue_i=0</span>：把 <span>cache[i]</span> 直接写入本步输出缓冲，标记该 block 为“复用”，跳过前向。</li>\n<li>若 <span>rescue_i=1</span>：把 <span>i</span> 压入救援队列，队列按 block 在数据流中的顺序排序（保证重算时激活依赖正确）。</li>\n<li>按队列顺序对每个救援 block 执行前向，得到 <span>y_i</span>；做残差修正 <span class=\"formula\">$$\\tilde{y}_i = y_i + \\alpha\\,(y_i - \\text{cache}[i])$$</span> 其中 <span>α</span> 是修正系数，取小值以抑制单步过冲；随后 <span>cache[i] ← ỹ_i</span>，并把 <span>k_i^{t-1} ← k_i^t</span> 供下一步使用。</li>\n<li>全部 block 汇聚后交给 scheduler 更新 latent，进入下一步。</li>\n</ul>\n<p>残差修正项 <span>α(y_i − cache[i])</span> 的作用是把“重算结果与旧缓存的差”部分保留下来，而不是直接用新值覆盖。若 <span>α=1</span>，等价于完全信任重算，语义切换处响应快但相邻 step 之间会出现跳变；若 <span>α=0</span>，等价于不修正，救援形同虚设。工程上 <span>α</span> 与 <span>τ</span> 是一对耦合参数：<span>τ</span> 越松、救援越少，<span>α</span> 就应越大以补偿漏检。这一对参数没有解析最优，需按分辨率与步数分桶标定。</p>\n<p>系统代价在这里显形：救援队列是动态长度，重算的 block 集合每步不同，导致 kernel 的 grid 尺寸与执行序不固定。这正是“分支破坏 kernel 规整性”的具体所指——不是分支指令本身慢，而是它让原本可以整块捕获的 CUDA Graph 出现动态拓扑。缓解手段是分段捕获：把“判定+复用写回”捕获为一段静态图，“救援重算”按可能的队列长度预捕获若干变体（如 1/2/4/8 个 block 的固定形状），运行时按实际队列长度选图重放。代价是图变体占用额外 device 内存与捕获时间，且队列长度超出预捕获档位时回退到非图路径，单步时延收益被抵消——这正是失败模式里“捕获失败或重放错误”的由来。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-17\">十七 · 显存账：缓存占用如何挤压 batch 容量</h3>\n<p>缓存不是免费的。每个 block 的输出缓存占 <span class=\"formula\">$$M_{\\text{cache}} \\approx L \\cdot B \\cdot S \\cdot H \\cdot d_{\\text{bytes}}$$</span> 其中 <span>L</span> 为 block 数、<span>B</span> 为批大小、<span>S</span> 为序列（patch）长度、<span>H</span> 为 hidden 维、<span>d_bytes</span> 为每元素字节数。在 Blackwell 上，高分辨率大 DiT 的 <span>S</span> 与 <span>H</span> 都大，<span>M_cache</span> 会与 KV cache、激活缓冲争抢同一块 HBM。B200/GB200 的 HBM 容量虽大，但推理服务里 KV 与激活已占大头，缓存只能分到剩余预算。</p>\n<p>由此得到 batch 容量的约束式：<span class=\"formula\">$$B_{\\max} \\approx \\left\\lfloor \\frac{M_{\\text{HBM}} - M_{\\text{KV}} - M_{\\text{act}} - M_{\\text{weight}}}{L \\cdot S \\cdot H \\cdot d_{\\text{bytes}}} \\right\\rfloor$$</span> 这个式子的工程含义是：缓存机制让单步变快（时延降 20%–40%），但可能让 <span>B_max</span> 下降，吞吐 = 批大小 / 单步时延，两者相抵后吞吐可能不升反降。判断是否划算，要看 <span>B_max</span> 的下降比例是否小于单步时延的下降比例。若缓存把 <span>B_max</span> 从 8 压到 4 而单步只快 30%，吞吐是净亏的。因此部署时必须把缓存与 KV/激活放进统一的显存预算里规划，而不是把缓存当作“额外的小开销”。</p>\n<p>降低 <span>M_cache</span> 的直接手段是缓存精度：输出缓存用 FP8 甚至 NVFP4 存储，键保持 BF16。这能把 <span>d_bytes</span> 压到 1 或 0.5，代价是复用 block 的输出带量化噪声，且残差修正要在低精度域做，<span>α</span> 需相应调小。另一个手段是只缓存部分 block（例如只缓存相似度长期偏高的浅层 block），把 <span>L</span> 换成实际缓存 block 数，牺牲一部分复用率换 batch 容量。这两条都属于容量规划层面的取舍，需与 SLO 一起定。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-18\">十八 · 阈值标定与失败模式的量化定位</h3>\n<p><span>τ</span> 的标定不能靠单点试错，而应按“分辨率 × 步数 × 语义切换密度”分桶。对每个桶，采集若干 step 的 <span>s_i</span> 分布，观察双峰结构：复用 block 的 <span>s_i</span> 集中在高位，语义切换处的 block <span>s_i</span> 落在中低位。阈值应设在两峰之间的谷底偏高一侧，既保住复用率又不漏救援。若分布没有明显双峰（例如步数很少、相邻 step 差异普遍大），说明该工况不适合本机制，应直接关闭缓存路径。</p>\n<p>失败模式的量化定位可以这样组织：漏救援的代价体现为画质退化，可用救援队列长度与实际语义变化 block 数的比值来监控——比值长期偏低即阈值过松；CUDA Graph 断裂的代价体现为单步时延的方差，若分段捕获后时延方差反而变大，说明图变体切换开销超过了收益；显存挤压的代价直接体现在 <span>B_max</span> 上，监控 batch 实际并发与理论 <span>B_max</span> 的差距即可发现。三者中，前两者影响单步时延与一致性，第三者影响吞吐，需分开度量，不能用一个“端到端时延”指标掩盖。</p>\n<p>最后落到一个具体工程判断：在 Blackwell 上部署这套机制，先做两件事——测单 block 的 <span>T_ℓ</span> 与 <span>T_read+T_write</span> 之比，确认净收益不等式成立；再按目标分辨率的 <span>M_cache</span> 反推 <span>B_max</span>，确认吞吐不亏。两项都过，才值得投入 CUDA Graph 分段捕获与阈值分桶标定的工程量；任一项不过，机制在该工况下不成立，应把算力留给别的优化路径。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-19\">十九 · 边界、失效条件与系统代价：这套缓存方案在什么情况下会反噬</h3>\n<p>把复用判据写成逐 block 的余弦相似度 $s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})$，再以阈值 $\\tau$ 二值化，形式上很干净，但它隐含了一个强假设：语义切换在 block 维度上是稀疏且可被键向量捕捉的。推导的关键一步在于把单步时延拆成 $\\sum_{\\ell}(1-\\text{reuse}_\\ell)T_\\ell+T_{\\text{cache}}$——这个式子只有在被跳过的 block 确实不贡献新信息时才成立。一旦 $\\tau$ 偏松，语义切换处的 block 相似度仍可能越过阈值，缓存输出被直接送进 scheduler 更新 latent，漂移不会在局部被拦住，而是沿着后续 step 放大成画面局部错位与跨 step 一致性下降。此时救援队列形同虚设，收益全部来自“少算”，代价却由画质承担。</p>\n<p>第二个失效点是执行路径的规整性。逐 block 判定天然产生数据相关的分支：哪些 block 跳过、哪些进救援队列，在 launch 前不可静态确定。这会破坏 kernel 的规整发射，若不做 CUDA Graph 分段捕获，捕获阶段遇到分支会失败或重放时读到错误的缓存指针，单步时延收益被抵消甚至倒挂。工程上的可行做法是把“判定 + 救援调度”与“重算前向”拆成两段图：前一段允许主机侧读相似度、生成救援 block 列表，后一段按固定模板发射重算 kernel，残差修正作为独立小 kernel 写回缓存。伪代码落到可实现层面即：对每个 block 计算 $s_i$，$s_i&gt;\\tau$ 则置复用位、否则压入救援队列；救援队列非空时按 block id 排序后批量重算，输出与缓存做残差相加再写回；最后统一汇聚进 scheduler。排序是为了让重算 kernel 的访存模式可预测，避免随机 block 顺序拖垮带宽利用率。</p>\n<p>第三个代价是显存。缓存按 block 输出整份保留，高分辨率大 DiT 下这部分占用与 KV、激活争抢同一预算，直接压缩 batch 容量。用一张小表看清权衡：</p>\n<table class=\"mini\"><thead><tr><th>配置方向</th><th>单步时延</th><th>显存占用</th><th>batch 容量</th><th>主要风险</th></tr></thead><tbody><tr><td>阈值偏紧、救援频繁</td><td>收益收窄</td><td>缓存仍需保留</td><td>受限</td><td>分支多、图捕获复杂</td></tr><tr><td>阈值偏松、救援稀疏</td><td>降 20%–40%</td><td>同上</td><td>受限</td><td>语义切换处漏救援、画质漂移</td></tr><tr><td>降分辨率/减缓存精度</td><td>收益不变</td><td>下降</td><td>回升</td><td>缓存键失真、判定失准</td></tr></tbody></table>\n<p>由此得出适用边界：该方案适用于相邻 step 输出相似度高、语义切换稀疏的多步扩散采样，且无需重训练是其核心优势；它与固定间隔缓存、步数蒸馏、一致性模型的区别正在于只改单步内计算路径而不改采样轨迹。规模上限由缓存显存决定——当缓存挤占使 batch 容量下降时，吞吐可能不升反降，此时应优先把缓存与 KV/激活纳入统一显存预算，按分辨率与步数分桶设定 $\\tau$ 与救援上限，而不是一味追高单步时延的 20%–40% 收益。</p>\n<h3 id=\"alg-feature-cache-rescue-sec-20\">二十 · 请求形态：什么样的采样轨迹才吃得到复用</h3>\n<p>特征缓存与动态救援的收益不是从硬件里挤出来的，是从采样轨迹的时间冗余里挤出来的。它要求请求本身是「多步、相邻步语义变化稀疏」的扩散采样：一个请求内部有足够多的 step 让缓存被反复命中，而 step 之间的 latent 演化又是平滑的。反过来，单步或少步请求（步数蒸馏、一致性类采样器）根本没有足够的相邻步对可供比较，缓存键还没写热就结束了，救援队列的开销反而成为纯负担。这类请求应当走别的路径，本算法对它们只增加分支与显存占用。</p>\n<p>把请求按「分辨率 × 步数」分桶是负载配方的第一层。分桶的意义不在于调度美观，而在于同一个桶内的请求共享同一套 block 拓扑与缓存形状：分辨率决定 latent 的空间尺寸，进而决定每个 DiT block 输出张量的字节数；步数决定一个请求内缓存被复用的期望次数。设单请求的缓存复用次数期望为 $N_{\\text{reuse}}$，则缓存带来的算力节省近似正比于 $N_{\\text{reuse}}\\cdot\\sum_\\ell \\text{reuse}_\\ell T_\\ell$，而缓存写入与相似度判定的固定开销只发生一次每 step。步数越多的桶，摊薄越充分；步数少的桶，摊薄不足。工程上应把短步数请求排除在缓存路径之外，或至少让它们与长步数请求分属不同队列，避免短请求把缓存显存占住却几乎不产生命中。</p>\n<p>长度分布在这里指的不是文本 token 长度，而是「语义切换在 step 轴上的分布」。一段采样轨迹里，真正的语义跃迁往往集中在少数几个 step（构图定型、主体细节切换、风格收敛），其余 step 是缓慢的精修。这个分布越稀疏、越集中在少数 step，动态救援的局部化优势越明显；反之，如果轨迹上每一步都在大幅改变语义（例如高噪声区间的前几步、或强引导系数下的剧烈调整），相似度判定会持续低于阈值，几乎所有 block 都进救援队列，缓存退化为「算了相似度但没省下计算」的空转。</p>\n<p>一个具体的判断例子：同一套 1024 级分辨率、数十步的采样配方，若把引导系数调高到让每步 latent 位移显著增大，则 $\\cos(\\mathbf{k}_i^t,\\mathbf{k}_i^{t-1})$ 在多数 block 上跌破 $\\tau$，救援队列长度接近 block 总数，单步时延退回全量重算并叠加判定开销——此时 20%–40% 的单步时延收益不但拿不到，还会反向亏损。负载配方必须把这类「高位移轨迹」识别出来并旁路缓存路径。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-21\">二十一 · 并发与批大小：缓存显存是第一约束</h3>\n<p>并发维度的配方与算力维度相反：缓存算法省的是单请求内的算力，吃的是显存。每个活跃请求都要为每个 DiT block 保留一份上一步输出缓存，缓存字节数正比于 batch 内请求数、block 数与单 block 输出张量尺寸。高分辨率大 DiT 下，这份缓存与 KV cache、激活峰值争抢同一块 HBM，直接压缩可承载的 batch 容量。因此并发配方不是「越大越好」，而是要在显存预算里给缓存划出一条硬边界，再倒推最大并发。</p>\n<div class=\"formula\">$$\\text{Mem}_{\\text{cache}} \\approx B \\cdot \\sum_{\\ell} \\text{bytes}(h_\\ell),\\qquad B_{\\max}=\\left\\lfloor \\frac{\\text{Mem}_{\\text{budget}}-\\text{Mem}_{\\text{act}}-\\text{Mem}_{\\text{kv}}}{\\sum_\\ell \\text{bytes}(h_\\ell)}\\right\\rfloor$$</div>\n<p>其中 $B$ 为并发批大小，$\\text{bytes}(h_\\ell)$ 是第 $\\ell$ 个 block 缓存张量的字节数。这个式子给出的工程判断很直接：缓存让单步变快，但 $B_{\\max}$ 下降会让吞吐（tokens 或 images per second）不升反降。吞吐是并发与单步时延的乘积，单步降 20%–40% 而并发被砍掉一半，净效果是负的。所以配方的核心是找那个让 $B\\cdot T_{\\text{step}}$ 最优的批大小，而不是把批开到显存极限。</p>\n<p>批大小的第二个约束来自分支规整性。相似度判定与救援调度是数据相关的控制流：同一批内不同请求、不同 block 的复用决策不一致，SIMT 执行会分裂。批越大，批内决策的分歧概率越高，kernel 规整性越差。这与「批越大越好」的直觉冲突，构成一个真实的配方张力：小批利于分支收敛与 CUDA Graph 分段捕获，大批利于摊薄权重读取与提升吞吐。实践中常取中等批并配合分段捕获，把判定段与重算段拆成可重放的图段。</p>\n<p>具体例子：在 GB200 NVL72 单节点上跑高分辨率大 DiT，若把缓存张量按 block 全量驻留，显存预算被切成三份（激活、KV、缓存），可承载并发显著低于无缓存路径；此时把缓存改为「仅保留命中率高的 block 子集」或按需换出，可以把 $B_{\\max}$ 拉回来，代价是部分 block 失去复用机会。这是负载配方与显存配方交界处的典型取舍。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-22\">二十二 · 负载不对时的三种崩塌</h3>\n<p>第一种崩塌是阈值过松导致的漏救援。$\\tau$ 设得低，相似度判定过于宽松，语义切换处的 block 被判为可复用，缓存输出未经重算就直接汇入 scheduler 更新 latent。后果不是单步变慢，而是画面局部漂移与跨 step 一致性下降——错误被写进 latent 后会在后续 step 被放大，且因为缓存被污染，下一步的相似度判定也建立在错误基准上。这类失败在指标上表现为画质退化而非时延异常，监控若只看延迟会完全漏掉。</p>\n<p>第二种崩塌是分支破坏 kernel 规整性。相似度判定与救援调度引入数据相关跳转，若未做 CUDA Graph 分段捕获，会出现捕获失败或重放错误；即便捕获成功，重放时若决策路径与捕获时不一致，图段边界处的同步与内存复用也可能出错。结果是单步时延收益被抵消甚至反转：判定开销、图重捕开销、以及因分支导致的 warp 利用率下降叠加在一起。这是「算法正确但系统不配合」的典型，配方上必须把 CUDA Graph 分段捕获作为前置条件而非优化项。</p>\n<p>第三种崩塌是缓存挤占显存使 batch 容量下降。前面已给出 $B_{\\max}$ 的式子，其后果是吞吐不升反降：单步时延降了 20%–40%，但并发被显存砍掉更多，单位时间产出的请求数下降。更隐蔽的是，缓存与激活峰值争抢会在高分辨率下触发显存碎片与分配抖动，表现为偶发的长尾延迟，破坏 SLO 的尾部指标。SLO 以单步时延为目标时，这类长尾比平均时延更致命。</p>\n<p>三种崩塌的共同点是：它们都不体现在「算法是否跳过了 block」这一层，而体现在系统层的画质、图捕获、显存与尾延迟上。负载配方的作用就是在请求进入缓存路径之前，用形态、长度分布、并发与批大小四个维度把这些崩塌条件排除掉。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-23\">二十三 · 配方判据：把请求分流的可执行规则</h3>\n<p>把上面的分析收敛成可执行的分流规则，比调 $\\tau$ 更重要。第一条判据是步数下限：请求的采样步数必须足够多，使得缓存写入与判定开销能被复用收益摊薄；低于该下限的请求直接走全量重算路径。第二条判据是轨迹位移预判：用前若干 step 的相似度统计（或引导系数、噪声日程等配方元数据）估计整条轨迹的救援比例，救援比例过高则旁路缓存。第三条判据是显存余量：进入缓存路径前检查 $\\text{Mem}_{\\text{budget}}-\\text{Mem}_{\\text{act}}-\\text{Mem}_{\\text{kv}}$ 是否足以容纳该请求的缓存张量，不足则降级为部分 block 缓存或排队。</p>\n<ul>\n<li>步数少、位移大、显存紧的请求：不进缓存路径，避免负收益。</li>\n<li>步数多、位移稀疏、显存有余的请求：进缓存路径，享受 20%–40% 单步时延收益。</li>\n<li>介于两者之间的请求：进部分缓存路径，只对命中率高的 block 子集驻留缓存。</li>\n</ul>\n<p>具体例子：一个混合负载的服务里，长步数精修请求与短步数快速预览请求共存。若不加分流，短请求会占住缓存显存却不产生命中，把长请求的 $B_{\\max}$ 挤下去，整体吞吐下降。按上述三条判据分流后，缓存显存只分配给真正吃得到复用的请求，长请求的批大小得以恢复，短请求走全量路径保持其低延迟特性。</p>\n<p>配方判据还需要与稳定性技巧联动：动态救援把漂移限制在局部 block，但救援比例本身是负载的函数。把救援比例作为运行时观测量反馈到分流决策，可以在负载漂移时自动收紧或放宽缓存路径的准入，而不是靠固定阈值硬扛。这一步把「负载配方」从静态配置变成闭环控制。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-24\">二十四 · 与相邻路径的负载边界</h3>\n<p>负载配方还要回答「什么时候不该用本算法」。固定间隔缓存按固定 step 周期复用、不检测相似度，它的负载画像更简单：只要步数够多就能摊薄，不依赖轨迹位移的稀疏性，但代价是在语义切换处必然引入漂移。本算法用逐 block 相似度判定与救援队列换来了对语义切换的局部化处理，代价是分支与显存。因此当负载的语义切换极其稀疏、且对画质退化容忍度低时，本算法的救援机制是必要的；当负载位移均匀、固定间隔缓存已能满足画质要求时，本算法的判定开销就是多余的。</p>\n<p>与步数蒸馏、一致性模型相比，本算法不改变采样轨迹与步数，只改单步内的计算路径。这意味着它的负载配方必须建立在「原采样配方不变」的前提上：步数、引导系数、噪声日程都是外部给定的，配方只能在给定轨迹上做分流与阈值调整，不能通过减步来规避位移大的区间。这也解释了为什么位移预判必须基于配方元数据而非事后统计——轨迹是固定的，能调的只有准入。</p>\n<p>工程判断落在最后这一步：负载配方的产出不是一组静态参数，而是一条准入边界加一个运行时反馈量（救援比例）。边界决定哪些请求进缓存路径，反馈量决定边界随负载漂移如何移动。把这两者接进调度器，缓存算法才在真实混合负载下稳定拿到那 20%–40% 的单步时延收益，而不是在负载不对时把收益吐回去还倒贴显存与尾延迟。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-25\">二十五 · 负载配方：什么样的请求才配得上这套缓存</h3>\n<p>这套按 block 相似度复用的方案，本质上是在单步内做一次“计算路径剪枝”，它的收益完全由请求形态决定。最匹配的负载是<strong>多步扩散采样、按分辨率与步数分桶</strong>的请求：同一 batch 内所有样本共享同一 step 索引，相邻 step 的 DiT block 输出高度相似，且语义切换稀疏——典型如高步数、中低分辨率的图像生成，或视频扩散中相邻帧间变化平缓的段落。此时 <span class=\"formula\">$$s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})$$</span> 在多数 block 上稳定超过阈值 $\\tau$，复用比例高，单步时延收益才落得到材料给出的 20%–40% 区间。反过来，步数很少、每步 latent 变化剧烈（高噪声起步、强引导、频繁语义切换）的请求，$s_i$ 大面积跌破 $\\tau$，救援队列几乎覆盖全部 block，等于白付了相似度判定与分支调度的开销，却拿不到任何跳过收益。</p>\n<p>批大小不是可以自由调的自由变量，而是被缓存显存反推出来的。每个被复用的 block 都要保留上一步输出作为缓存，高分辨率大 DiT 下这部分占用与 KV/激活直接争抢显存预算，于是 batch 容量受限：设单样本缓存占用 $M_{\\text{cache}}$、激活与 KV 占用 $M_{\\text{act}}$、可用显存 $M_{\\text{free}}$，则 <span class=\"formula\">$$B_{\\max}\\approx\\left\\lfloor \\frac{M_{\\text{free}}-M_{\\text{static}}}{M_{\\text{cache}}+M_{\\text{act}}}\\right\\rfloor$$</span> 当 $M_{\\text{cache}}$ 随分辨率上升而膨胀时，$B_{\\max}$ 下降的速度快于单步时延的下降速度，吞吐不升反降。这就是负载配方里必须写清的一条：<em>该方案适合“单步时延敏感、batch 不大”的 SLO，而不是“大 batch 拉吞吐”的 SLO</em>。以 20%–40% 的单步时延收益去换掉一半的 batch 容量，在吞吐导向的容量规划里是净亏。</p>\n<p>负载不对时的失效是分层的。第一层是阈值：$\\tau$ 设得过松，语义切换处的 block 被判为可复用，缓存输出未经救援直接汇入 scheduler 更新 latent，表现为画面局部漂移与跨 step 一致性下降；$\\tau$ 设得过紧，救援队列膨胀，收益归零。第二层是执行形态：相似度判定与救援调度引入数据相关分支，破坏 kernel 规整性，必须用 CUDA Graph 分段捕获；若负载中每个 step 的救援 block 集合都在变，分段边界难以稳定，捕获失败或重放错误会直接抵消时延收益。第三层是容量：缓存挤占显存使 batch 容量下降，在并发请求堆积时表现为排队延迟上升——单步变快了，端到端 SLO 反而更差。因此配方里应把“按分辨率与步数分桶、桶内固定 batch 与阈值、桶间独立规划显存预算”作为准入条件，而不是把所有扩散请求无差别灌进同一队列。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>复用率</th><th>主要代价</th><th>判断</th></tr></thead><tbody><tr><td>高步数、语义切换稀疏</td><td>高</td><td>缓存显存</td><td>适配，时延收益 20%–40%</td></tr><tr><td>低步数、每步剧变</td><td>低</td><td>判定与分支开销</td><td>不适配，收益被抵消</td></tr><tr><td>高分辨率大 DiT、大 batch</td><td>中</td><td>batch 容量受限</td><td>需重排显存预算后再评估</td></tr></tbody></table>\n<h3 id=\"alg-feature-cache-rescue-sec-26\">二十六 · 硬件档位：按缓存驻留量反推 SM 与显存档</h3>\n<p>部署特征缓存与动态救援，第一刀不是切并行，而是切硬件档位——因为这条算法的容量约束来自缓存本身，而不是权重或 KV。缓存驻留量由 block 数 $L$、每 block 输出张量形状与精度决定：若第 $\\ell$ 个 block 输出为 $h_\\ell \\in \\mathbb{R}^{B\\times S\\times d}$，以 $b$ 字节/元素存储，则单请求缓存占用为</p>\n<div class=\"formula\">$$M_{\\text{cache}} = \\sum_{\\ell=1}^{L} B \\cdot S_\\ell \\cdot d_\\ell \\cdot b \\cdot \\alpha$$</div>\n<p>其中 $\\alpha$ 为缓存份数系数（单步缓存取 1，若保留历史窗口则大于 1）。$S_\\ell$ 随分辨率线性增长，$d_\\ell$ 由模型宽度决定。这个式子决定了档位选择的方向：高分辨率大 DiT 下 $M_{\\text{cache}}$ 与激活、KV 同池竞争，必须把缓存当作一等公民纳入显存预算，而不是“剩下多少用多少”。工程判断是：先按目标分辨率与批大小算出 $M_{\\text{cache}}$，再倒推可用显存档位；若单卡 HBM 装不下“权重 + 峰值激活 + 缓存 + KV”，则降档到更小分辨率分桶，或把缓存精度压到 FP8/FP16 存储（缓存只用于复用与残差修正，不需要与计算精度同级）。SM 档位方面，救援路径需要额外算力冗余：跳过 block 释放的算力不能全部折算为吞吐收益，因为救援 block 的重算与残差修正要在同一 step 内完成，形成尖峰。B200 与 GB200 NVL72 的差异在这里体现为“单 step 尖峰能否被单卡吸收”——单卡档位适合救援率低、语义切换稀疏的负载；机柜级档位适合把救援重算卸载到邻近 GPU 的冗余算力上，但跨卡同步会引入额外时延。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-27\">二十七 · 并行拓扑：把分支收敛在卡内，把救援留在本地</h3>\n<p>相似度判定与救援调度引入分支，破坏 kernel 规整性，这是拓扑设计的核心约束。拓扑选择的第一原则是：<strong>让分支发生在单卡内部，让跨卡通信只承载规整的集合通信</strong>。若把 block 级复用决策做成跨卡依赖，每个 step 都要在 block 粒度上做一次 all-reduce 或点对点同步，分支的不规整性会被放大成通信抖动，单步时延收益被抵消。</p>\n<p>可行拓扑是张量并行（TP）沿隐藏维切分、流水并行（PP）沿 block 层切分，但 PP 与动态救援天然冲突：救援 block 的重算会打乱流水节拍，stage 间气泡随救援率上升。因此更稳的做法是把 PP 度压到最小，优先用 TP + 数据并行（DP）复制：每个 DP 副本独立持有自己的缓存与救援队列，block 级决策完全本地化，跨卡只做梯度无关的推理批分发。TP 组内，block 输出被切分到多卡，余弦相似度需在切分维度上做局部归约——把 $\\mathbf{k}_i^t \\cdot \\mathbf{k}_i^{t-1}$ 的分子按 TP rank 分片计算后 all-reduce 求和，分母的范数同理，这是一次小规模、规整的集合通信，可以并入 CUDA Graph 的固定段。NVLink 5 的高带宽使这次归约的代价相对单步时延可忽略，但前提是归约被静态捕获，而不是在分支里动态发起。</p>\n<p>代价面：TP 度增大会缩小每卡上的 block 计算量，使“跳过 block”释放的算力更碎片化，救援重算的尖峰更难被摊平；DP 副本增多则线性放大缓存总占用，$M_{\\text{cache}}$ 随副本数成倍增长。工程判断是 TP 度取“单卡能容纳一个 block 的完整中间激活”为下限，DP 度取“缓存总占用不超过显存预算”为上限，两者夹出的区间通常很窄，这也是该算法在高分辨率下 batch 容量受限的拓扑根源。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-28\">二十八 · 量化方案：计算精度与缓存精度分离</h3>\n<p>量化方案要分两层看：前向计算的精度决定救援重算的成本与数值稳定性，缓存的存储精度决定容量。两者不必同级。计算侧沿用 Blackwell 的 NVFP4/FP8 路径（细节见同模块量化条目），但缓存侧建议用高于计算精度的格式存储 block 输出——原因是残差修正对缓存值的误差敏感：救援 block 的输出要与缓存做残差修正后写回，若缓存本身是低精度，残差会被量化噪声淹没，跨 step 累积后表现为局部漂移。</p>\n<p>给出一个可复现的判据：设缓存以 $b_c$ 字节存储、计算以 $b_f$ 字节进行，残差修正的相对误差量级约为 $2^{-8b_c}$ 与 $2^{-8b_f}$ 的叠加。当救援率 $r$ 较低时，误差累积步数少，$b_c = b_f$ 即可；当 $r$ 上升（语义切换密集的负载），累积步数增多，应把 $b_c$ 提高一档，用容量换一致性。反过来，若显存吃紧，优先压计算精度而非缓存精度：计算精度的降低只影响被重算的 block（占比 $r$），缓存精度的降低影响所有被复用的 block（占比 $1-r$），后者的暴露面更大。</p>\n<p>代价面：缓存精度每提高一档，$M_{\\text{cache}}$ 翻倍，直接压缩 batch 容量；计算精度降低则改变救援重算的时延 $T_\\ell$，进而改变单步时延公式中的重算项。量化方案的选择因此不是孤立的数值问题，而是与批调度耦合的容量问题——这正是下一节要处理的。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-29\">二十九 · KV 策略与显存预算：缓存、KV、激活三方分池</h3>\n<p>扩散推理中 KV 的角色与自回归不同：多步采样每步的注意力 KV 在 step 间通常不保留（除非做跨 step 注意力复用），因此 KV 占用是瞬态的、随 batch 线性增长；而特征缓存是跨 step 驻留的、随 block 数线性增长。两者争抢同一块 HBM，预算分配必须显式化。给出预算不等式：</p>\n<div class=\"formula\">$$M_{\\text{weight}} + M_{\\text{act}}^{\\text{peak}} + M_{\\text{KV}}(B) + M_{\\text{cache}}(B) \\le M_{\\text{HBM}} \\cdot \\eta$$</div>\n<p>其中 $\\eta$ 为安全水位（留出碎片与临时缓冲）。$M_{\\text{KV}}(B)$ 与 $M_{\\text{cache}}(B)$ 都随批大小 $B$ 线性增长，因此可行批大小由两者之和的上界决定：</p>\n<div class=\"formula\">$$B_{\\max} = \\left\\lfloor \\frac{M_{\\text{HBM}}\\eta - M_{\\text{weight}} - M_{\\text{act}}^{\\text{peak}}}{m_{\\text{KV}} + m_{\\text{cache}}} \\right\\rfloor$$</div>\n<p>$m_{\\text{KV}}$ 与 $m_{\\text{cache}}$ 分别为单请求的 KV 与缓存占用。这个式子是部署配方的定量骨架：它说明为什么高分辨率下吞吐不升反降——分辨率抬高 $S_\\ell$，$m_{\\text{cache}}$ 与 $m_{\\text{KV}}$ 同时上升，$B_{\\max}$ 下降，跳过 block 省下的算力被批容量损失吃掉。KV 策略上，可做的取舍是：对缓存复用的 block，其注意力 KV 若也跨 step 复用，则 KV 从瞬态变为驻留，进一步挤压预算；因此建议缓存复用只作用于 block 输出，不延伸到注意力 KV，保持 KV 的瞬态属性，让预算不等式中的 $M_{\\text{KV}}$ 项可控。另一个手段是分桶：按分辨率与步数分桶，高分辨率桶用小批、低分辨率桶用大批，使每个桶内的 $B_{\\max}$ 都贴近上界，而不是用统一批大小迁就最坏桶。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-30\">三十 · 调度参数：阈值、救援率与 CUDA Graph 分段</h3>\n<p>调度参数里最关键的三个量是相似度阈值 $\\tau$、救援率 $r$ 与 CUDA Graph 的分段粒度。$\\tau$ 决定复用判定的松紧：$\\tau$ 过松（偏低）会在语义切换处漏救援，缓存输出直接进入 scheduler，造成局部漂移与跨 step 一致性下降；$\\tau$ 过紧则复用率下降，单步时延收益向零收敛。可复现的调参思路是把 $\\tau$ 与负载的语义切换密度绑定：对切换稀疏的负载（如以背景为主的生成），$\\tau$ 可取较高值以放大复用；对切换密集的负载（如多主体交互），$\\tau$ 需下调，用更多救援换取一致性。$\\tau$ 不应是全局常数，按 block 深度分层更稳——浅层 block 输出变化快，深层 block 输出趋于稳定，分层阈值能在不增加救援率的前提下提高总复用率。</p>\n<p>救援率 $r$ 是调度参数的观测量，也是容量规划的输入：单步时延近似为</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\sum_{\\ell} (1-\\text{reuse}_\\ell)\\, T_\\ell + T_{\\text{cache}} + T_{\\text{rescue}}(r)$$</div>\n<p>其中 $T_{\\text{rescue}}(r)$ 随救援率上升而增长，且因分支不规整而带有非线性。工程上把 $r$ 作为运行时指标暴露出来，当 $r$ 超过某条线时触发降级（例如临时提高 $\\tau$ 或缩小批），比静态配置更能守住 SLO。</p>\n<p>CUDA Graph 分段是维持执行效率的必要条件：相似度判定与救援调度引入分支，若整图捕获会在分支处断裂或重放错误。做法是把一个 step 切成固定段——相似度计算段、复用读取段、救援重算段、残差修正与汇聚段——每段内部无分支、可静态捕获，段间用轻量同步衔接。分段粒度越细，捕获越稳，但段间同步开销越大；粒度越粗，分支暴露越多。经验判据是让“救援重算段”成为独立段，因为它的执行长度随 $r$ 变化，最不适合与规整段混捕。代价面：分段引入的同步开销直接计入 $T_{\\text{cache}}$ 项，若分段过细，这部分开销会侵蚀 20%–40% 的单步时延收益；若不做分段，捕获失败或重放错误会让收益归零。因此分段粒度本身就是调度参数的一部分，需与 $\\tau$、批大小联合调优，而不是事后补丁。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-31\">三十一 · 可复现配置思路：从预算不等式倒推参数</h3>\n<p>把上述四节收束成一条可复现的配置流程，顺序是“先定容量、再定拓扑、后调调度”：</p>\n<ul>\n<li>第一步，按目标分辨率与模型宽度算出 $m_{\\text{cache}}$ 与 $m_{\\text{KV}}$，代入预算不等式求 $B_{\\max}$；若 $B_{\\max}$ 小于 1，说明该分辨率在当前档位不可行，降分辨率或提缓存精度以外的压缩手段。</li>\n<li>第二步，按 $B_{\\max}$ 与单卡激活峰值确定 TP 度下限，按缓存总占用确定 DP 度上限；在区间内取使跨卡归约最小的组合，优先保证 block 级决策本地化。</li>\n<li>第三步，计算精度取 NVFP4/FP8 路径，缓存精度按救援率预期选档：$r$ 低则同级，$r$ 高则提高一档。</li>\n<li>第四步，CUDA Graph 按“相似度段 / 复用段 / 救援段 / 修正汇聚段”四段捕获，救援段独立，段间同步点数量作为调优变量记录。</li>\n<li>第五步，$\\tau$ 按 block 深度分层初始化，运行时监控 $r$ 与单步时延，$r$ 越线即触发降级策略。</li>\n</ul>\n<p>这条流程的产出不是一组固定超参，而是一张“分辨率桶 × 批大小 × $\\tau$ 分层 × 分段粒度”的配置表，每个桶独立满足预算不等式与 SLO。它的工程价值在于把三个失败模式前置到配置阶段拦截：阈值过松导致的漏救援由分层 $\\tau$ 与运行时 $r$ 监控兜住；分支导致的捕获断裂由四段捕获兜住；缓存挤占导致的批容量下降由预算不等式在第一步就暴露，而不是等到吞吐实测才发现。最终落点是一个判断：这套算法的部署上限不由算力决定，而由 $M_{\\text{cache}}$ 与 $M_{\\text{KV}}$ 之和相对显存预算的占比决定——当这个占比逼近安全水位时，任何调度参数的调优都只是在容量约束内做边际交换，真正的扩容手段是把缓存移出 HBM 或降低分辨率桶的驻留量。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-32\">三十二 · 部署配方的失效边界：从阈值到显存预算的三条断裂线</h3>\n<p>这套缓存方案的部署配方没有统一的硬件档位与并行拓扑模板，可复现的配置思路只能围绕三个硬约束展开：缓存显存预算、CUDA Graph 分段捕获的粒度、以及相似度阈值 τ 与救援队列规模的联动。设单 block 缓存张量大小为 $M_b$、block 数为 $L$、批大小为 $B$，则缓存显存占用 $M_{\\text{cache}} = B \\cdot L \\cdot M_b$，它与 KV/激活共享同一预算，因此批容量的上界为 $B_{\\max} = \\lfloor (M_{\\text{total}} - M_{\\text{act}} - M_{\\text{kv}}) / (L \\cdot M_b) \\rfloor$。工程判断是：先按分辨率与步数分桶，用最小分辨率桶标定 $M_b$，再反推每个桶的 $B_{\\max}$，而不是先定 batch 再算显存——后者在高分辨率大 DiT 上必然撞墙。</p>\n<p>第一条断裂线是阈值。τ 过松时，语义切换处的 block 相似度仍高于阈值，救援队列为空，缓存输出直接汇入 scheduler 更新 latent，表现为画面局部漂移与跨 step 一致性下降；τ 过紧则救援队列膨胀，$\\sum_\\ell (1-\\text{reuse}_\\ell) T_\\ell$ 项吃掉全部收益，单步时延回落到全量重算水平。可复现的做法是把 τ 与救援比例绑定：先离线统计每个 block 在采样轨迹上的相似度分布，取使救援 block 占比落在个位数百分比区间的 τ，并在语义切换密集的早期 step 单独放宽救援触发条件。收益区间 20%–40% 只在相似度高、语义切换稀疏的采样形态下成立，超出该形态材料未给出收益保证。</p>\n<p>第二条断裂线是执行规整性。相似度判定与救援调度引入数据相关分支，破坏 kernel 规整性，必须用 CUDA Graph 分段捕获：把“判定段”“复用读取段”“救援重算段”“残差写回段”分别捕获为独立 graph，段间用主机侧或设备侧条件跳转衔接。若整图一次性捕获，分支会导致捕获失败或重放错误，单步时延收益被完全抵消。代价是段边界处的同步开销与 graph 重放启动开销，在低 batch、短 step 场景下这部分固定开销占比上升，需按 step 时延预算决定分段粒度。</p>\n<p>第三条断裂线是吞吐反噬。缓存挤占显存使 $B_{\\max}$ 下降，若单步时延降幅不足以补偿批容量损失，吞吐不升反降。判据可写成 $\\frac{T_{\\text{step}}^{\\text{base}}}{T_{\\text{step}}^{\\text{cache}}} &gt; \\frac{B_{\\max}^{\\text{base}}}{B_{\\max}^{\\text{cache}}}$，不满足即应退回固定间隔缓存或缩小缓存覆盖的 block 范围。下表给出三条断裂线的触发条件与工程动作。</p>\n<table class=\"mini\"><thead><tr><th>断裂线</th><th>触发条件</th><th>系统代价</th><th>工程动作</th></tr></thead><tbody><tr><td>阈值漏救援</td><td>语义切换处 $s_i&gt;\\tau$</td><td>画质漂移、一致性下降</td><td>按 block 统计分布标定 τ，早期 step 放宽</td></tr><tr><td>Graph 捕获断裂</td><td>整图捕获含数据相关分支</td><td>捕获失败/重放错误，收益归零</td><td>四段分段捕获，段间条件跳转</td></tr><tr><td>显存挤占</td><td>$B_{\\max}$ 下降超过时延收益</td><td>吞吐不升反降</td><td>缩小缓存 block 覆盖或退回固定间隔</td></tr></tbody></table>\n<h3 id=\"alg-feature-cache-rescue-sec-33\">三十三 · 显存账本：缓存是第二套激活</h3>\n<p>特征缓存的容量代价常被低估。它不是“顺手存一点”，而是为每个 DiT block 的每个 token 位置保留一份与激活同量级的张量：若 block 输出维度为 $d$、序列长度为 $L$、层数为 $N_\\ell$、批大小为 $B$，则缓存显存为</p>\n<div class=\"formula\">$$M_{\\text{cache}} = B \\cdot L \\cdot d \\cdot N_\\ell \\cdot b_{\\text{bytes}}$$</div>\n<p>其中 $b_{\\text{bytes}}$ 在 BF16 下为 2、FP8 下为 1。关键在于它与激活峰值同阶：激活在 block 前向结束后即可释放，缓存却必须跨 step 存活，于是单步内原本“用完即弃”的显存被长期占用。高分辨率大 DiT 下 $L$ 随潜空间网格平方增长，$N_\\ell$ 又常在数十层量级，缓存很容易与 KV、临时激活争抢同一块预算。工程上必须把缓存当作与 KV 并列的第二套常驻账目，在显存规划阶段就切出固定配额，而不是让分配器在峰值时刻临时挤占——否则 batch 容量会在高分辨率桶上被迫下调，吞吐收益被容量损失吃掉。</p>\n<p>具体例子：一个按分辨率分桶的服务，低分辨率桶能跑较大 batch，缓存占比小；一旦切到高分辨率桶，$L$ 上升数倍，缓存与激活同时膨胀，同一张卡上可容纳的并发请求数骤降。此时单步时延虽降 20%–40%，但每秒完成的请求数未必上升，SLO 以单步时延为目标时看似达标，以吞吐为目标时反而倒退。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-34\">三十四 · 带宽与分支：规整性被打破的代价</h3>\n<p>缓存命中路径并不免费。跳过前向省下的是算力，但读取缓存要走显存带宽：每个被复用的 block 需把上一步输出整块读回，写回时又要写一次。设命中率为 $r$，则单步的缓存读写流量近似为</p>\n<div class=\"formula\">$$W_{\\text{step}} \\approx 2 \\cdot r \\cdot B \\cdot L \\cdot d \\cdot N_\\ell \\cdot b_{\\text{bytes}}$$</div>\n<p>当算力不再是瓶颈（低 batch、小分辨率），这笔流量会直接顶到 HBM 带宽上限，复用反而变成带宽换算力，收益打折。更麻烦的是分支本身：相似度判定要在每个 block 前插入一次归约与比较，命中与救援走不同路径，kernel 的规整执行流被打断。未做 CUDA Graph 分段捕获时，捕获会因控制流分叉失败或重放错误，单步时延收益被抵消——这是失败模式里最隐蔽的一条，因为它不报错，只是悄悄退回逐 kernel 启动的开销。</p>\n<p>工程判断：把“判定—命中—救援”切成三段独立捕获的图，段间用显式同步衔接，让每段内部保持无分支的规整 kernel；判定段只输出一个布尔掩码与救援索引表，命中段按掩码做 gather，救援段按索引表做稀疏重算。代价是段间同步引入固定延迟，在步数多、单步本就短的场景里这笔固定开销占比上升，需要按步数分桶决定是否启用分段。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-35\">三十五 · 通信：救援队列是集合通信的扰动源</h3>\n<p>在张量并行或专家并行下，救援不再是一个卡内的局部决定。每个 rank 独立计算自己负责的 block 切片的相似度，命中与否可能不一致：若某 rank 判定命中而另一 rank 判定救援，汇聚时就会出现部分切片取自缓存、部分取自重算的拼接错误。因此判定必须跨 rank 对齐，通常做法是对相似度做一次 all-reduce 取最小（保守策略：任一 rank 认为需救援则全体救援），这引入一次小消息集合通信。</p>\n<p>这笔通信的代价不在字节数，而在同步点：它把原本可以异步流水的前向切成“判定屏障 + 计算”两段，屏障处的等待时间取决于最慢 rank。救援比例越高，all-reduce 后各 rank 的工作量越不均衡——被判救援的 block 集中在少数 rank 时，其余 rank 空转等待，形成负载倾斜。规模上去以后，这一项往往先于算力成为尾延迟的来源：平均步时延好看，P99 却被少数救援密集的 step 拖长。</p>\n<p>缓解方向是把救援索引表做成全局一致的稀疏列表，让各 rank 按同一列表重算对应切片，避免“各自为政”的拼接；同时把判定屏障与上一步的 scheduler 更新重叠，用流水掩盖同步等待。代价是调度器复杂度上升，且重叠窗口受限于 latent 更新的依赖关系，不能无限拉长。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-36\">三十六 · 功耗与频率：省下的算力不等于省下的瓦</h3>\n<p>跳过 block 前向确实减少 SM 的活跃周期，但缓存读写让 HBM 控制器保持高占用，而 HBM 功耗在整卡功耗中占比不低。于是出现一种反直觉情形：算力利用率下降，整卡功耗下降幅度却远小于算力下降幅度，能效比（每请求焦耳）改善有限。对以功耗为约束的部署（高密度机架、风冷边界），这意味着缓存带来的吞吐提升可能撞上功耗墙而非算力墙。</p>\n<p>更细的机制在频率：分支与稀疏重算让 SM 的占用率波动加剧，boost 频率在命中段与救援段之间反复切换，频率爬升的滞后使实际执行频率低于稳态值。工程上倾向于把救援段集中调度、命中段拉长，减少频率切换次数；代价是救援的即时性下降，漂移修正被推迟到下一个汇聚点，画质一致性略降。这是一个明确的取舍点，而非可以两头兼得的优化。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-37\">三十七 · 尾延迟：阈值与规模的非线性耦合</h3>\n<p>尾延迟的来源不是平均命中率，而是命中率的方差。语义切换处救援集中爆发，单步内救援 block 数从个位数跳到大批量，单步时延随之尖峰。设第 $t$ 步救援 block 数为 $R_t$，则</p>\n<div class=\"formula\">$$T_{\\text{step}}^{(t)} \\approx \\sum_{\\ell \\in \\text{hit}} T_{\\text{cache},\\ell} + \\sum_{\\ell \\in \\text{rescue}} T_{\\ell} + T_{\\text{sync}}$$</div>\n<p>$T_{\\text{sync}}$ 在并行拓扑下随 rank 数增长，而 $R_t$ 的尖峰与 $T_{\\text{sync}}$ 相乘，使 P99 步时延远超均值。阈值 $\\tau$ 越松，平均命中率越高、均值越好看，但语义切换处漏救援的概率上升，漂移在后续 step 累积；阈值越紧，救援频繁，尾延迟尖峰更密。规模上去以后先崩的通常是这一项：batch 增大使单步内并发的救援请求数上升，救援队列的排队时间非线性增长，而缓存显存又限制了并发上限，两者夹击下 P99 与吞吐同时恶化。</p>\n<p>工程判断：按分辨率与步数分桶后，为每个桶单独标定 $\\tau$，并在桶内监控救援比例的滑动分位数而非均值；当救援比例分位数越过设定线时，对该桶降 batch 或临时收紧缓存配额，用容量换尾延迟稳定。这比全局统一阈值更能在规模扩张时守住 SLO，代价是标定工作量与桶间参数不一致带来的运维复杂度。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-38\">三十八 · 规模放大后先崩的是显存预算，不是算力</h3>\n<p>把特征缓存放到单卡小 batch 上跑，收益曲线很漂亮；一旦分辨率与 DiT 宽度上去，第一个失效点几乎总是显存而不是 FLOPs。缓存要为每个被复用的 block 保留上一步输出，其字节数正比于 <span>batch × token 数 × 通道数 × 精度位宽</span>，而 token 数随分辨率平方增长。以高分辨率大 DiT 为例，单层 block 输出缓存就可能与 KV cache、激活峰值在同一预算池里争抢：激活是瞬态的、可被复用器回收，缓存却是跨 step 常驻的，于是显存规划从“峰值够不够”变成“常驻加峰值够不够”。直接后果是 batch 容量被压低，而扩散采样的吞吐几乎线性依赖 batch，单步时延降了 20%–40%，吞吐却可能因为并发请求数下降而不升反降。工程判断很直接：缓存预算必须先于 batch 决策被固定下来，把“每 block 缓存字节 × 可复用 block 数”作为硬约束写进容量模型，再倒推最大 batch，而不是先定 batch 再挤缓存。</p>\n<p>带宽侧的代价常被低估。复用路径虽然跳过了 MMA 与归一化，但仍要把缓存从 HBM 读回 SM，这一步的流量是 <span>复用 block 数 × 输出张量字节</span>；当复用率很高时，单步时间由计算受限转为访存受限，收益被 HBM 带宽吃掉一部分。用前文的步时模型看，<div class=\"formula\">$$T_{\\text{step}} \\approx \\sum_{\\ell} \\left(1-\\text{reuse}_\\ell\\right) T_\\ell + T_{\\text{cache}}$$</div>其中 <span>T_cache</span> 不只是查表开销，还包含缓存读回的带宽时间与残差修正的写回。救援队列让这一项更复杂：被标记的 block 要重算并做残差修正后写回，等于对同一块显存做“读—算—写”三段，救援比例上升时 <span>T_cache</span> 迅速膨胀，把省下的 <span>T_ℓ</span> 抵消。因此阈值 τ 不是画质参数而是系统参数：τ 偏松，救援比例低、带宽省，但语义切换处漏救援，缓存输出直接进 scheduler，出现局部漂移与跨 step 一致性下降；τ 偏紧，救援频繁，分支与写回把单步时延拉回全量重算附近。</p>\n<p>分支带来的规整性破坏是第三个崩点，且它先于规模出现。逐 block 的相似度判定与救援调度使执行路径依赖数据，kernel 的 grid 形状与 launch 序列不再固定，CUDA Graph 无法整图捕获，必须分段捕获并在段间插入条件跳转；一旦捕获断裂或重放时缓存指针错位，单步时延收益被抵消，甚至出现错误结果。规模上去后，段数随 block 数与 batch 桶数增长，图管理本身成为 host 侧开销。通信与功耗则体现在多卡与 NVL72 场景：缓存是每卡本地的，复用决策也是本地的，因此不引入额外集合通信，但分离式预填/解码或张量并行下，各 rank 的复用率不一致会造成 rank 间步时偏斜，尾延迟由最慢 rank 决定；跳过计算的 SM 进入低占用状态，功耗曲线出现锯齿，能效收益小于时延收益。尾延迟的真正来源是救援的突发性：语义切换步上大量 block 同时进入重算队列，形成单步内的尖峰，P99 步时可能高于全量重算的稳态值。</p>\n<table class=\"mini\"><thead><tr><th>规模维度</th><th>先崩的资源</th><th>表现</th><th>工程对策</th></tr></thead><tbody><tr><td>分辨率/DiT 宽度上升</td><td>显存</td><td>缓存常驻挤占 KV/激活，batch 容量受限，吞吐不升反降</td><td>缓存预算前置，按 block 字节倒推 batch</td></tr><tr><td>复用率上升</td><td>HBM 带宽</td><td>计算受限转为访存受限，T_cache 占比上升</td><td>缓存布局对齐、按 block 分块读回</td></tr><tr><td>语义切换步</td><td>尾延迟</td><td>救援队列突发，单步尖峰高于稳态</td><td>救援限流、按优先级分批重算</td></tr><tr><td>多卡/多 rank</td><td>同步与功耗</td><td>复用率不一致导致步时偏斜，SM 占用锯齿</td><td>跨 rank 对齐 τ 与救援策略</td></tr></tbody></table>\n<p>把这些放在一起，规模上限的判据不是“能跑多大模型”，而是“缓存常驻字节加激活峰值是否仍留得下目标 batch”。当高分辨率把单 block 缓存推到与 KV 同量级时，动态救援的收益区间被压缩：τ 的可行窗口变窄，救援比例对画质敏感，分段 CUDA Graph 的段数膨胀，尾延迟尖峰难以摊平。此时正确的工程动作是收缩复用粒度——只在相似度稳定且缓存字节小的浅层 block 上启用，深层与高分辨率段回退全量重算，用部分收益换回 batch 容量与可预测的 P99；而不是继续调 τ 去追那 20%–40% 的单步时延。</p>\n<h3 id=\"alg-feature-cache-rescue-sec-39\">三十九 · 精度失败：阈值漏救援与漂移的传播路径</h3>\n<p>特征缓存与动态救援的精度失败几乎全部收敛到一个根因：相似度判定的漏判。判定式 $s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})$ 只度量缓存键的方向一致性，而语义切换在键空间里往往表现为一次方向偏移叠加幅度突变——偏移足够大时 $s_i$ 跌破 $\\tau$ 被正确捕获，偏移小但幅度剧烈变化时 $s_i$ 仍可能高于 $\\tau$，block 被误判为可复用，缓存输出直接汇入 scheduler 更新 latent。这类漏救援不会在单步内暴露，而是在后续若干步被残差累积放大：一个被错误复用的 block 输出相当于给该步注入了一个有偏的隐状态，下一步的缓存键基于这个有偏状态计算，相似度判定随之失真，误差沿 block 链与 step 链双向传播。</p>\n<p>诊断这类问题的抓手不是看单步的 $s_i$ 分布，而是看救援率的时序曲线与救援位置的分布。健康状态下救援应呈稀疏脉冲：绝大多数 step 救援率接近零，仅在语义切换处出现局部尖峰。若观察到救援率长期贴地但输出质量下降，即为阈值过松的典型信号；若救援率持续偏高、单步时延收益被吞掉，则是阈值过紧。工程上把 $\\tau$ 做成按 block 深度分层的配置项而非全局单值——浅层 block 特征变化快、深层 block 语义稳定，用同一 $\\tau$ 必然在某一端失配。代价上，精度失败的代价不是算力而是返工：一次漏救援导致的画面漂移往往需要整条请求重跑，等效于把该请求的算力成本乘以采样步数，在批调度里表现为该 batch 的有效吞吐塌陷。</p>\n<p>具体例子：一个 1024×1024 分辨率、30 步采样的请求，在第 12 步发生主体轮廓切换，若该步有 6 个深层 block 的 $s_i$ 落在 $\\tau$ 之上被复用，则这 6 个 block 的缓存输出携带旧轮廓的残差进入 scheduler，第 13 至 18 步的 latent 持续偏向旧构图，直到某一步相似度自然跌破阈值触发大面积救援才被拉回，表现为画面在中段出现一次可见的结构抖动。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-40\">四十 · 显存失败：缓存预算与 batch 容量的零和</h3>\n<p>缓存占用的显存是这套算法最硬的约束。每个被复用的 block 需要保留上一步输出，其大小正比于该 block 的隐状态通道数与空间分辨率；高分辨率大 DiT 下，缓存总量与 KV、激活三者共享同一块显存预算。设单请求缓存占用为 $M_{\\text{cache}}$、激活峰值为 $M_{\\text{act}}$、可用显存为 $M_{\\text{avail}}$，则 batch 上限满足</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{M_{\\text{avail}}-M_{\\text{static}}}{M_{\\text{cache}}+M_{\\text{act}}}\\right\\rfloor$$</div>\n<p>其中 $M_{\\text{static}}$ 为权重与运行时固定开销。这个式子的含义是：缓存不是免费的加速，它按请求粒度线性吃掉 batch 容量。当 $M_{\\text{cache}}$ 增大到与 $M_{\\text{act}}$ 同量级时，$B_{\\max}$ 近似减半，单步时延虽降 20%–40%，但吞吐因并发请求数下降而不升反降——这正是材料中点明的“吞吐不升反降”失败模式。</p>\n<p>诊断 OOM 与容量塌陷要区分两种形态：硬 OOM 是分配失败、请求被拒，日志里表现为显存分配器抛错；软塌陷是 $B_{\\max}$ 被压到 1 至 2，调度器持续排队但 GPU 利用率上不去，表现为队列延迟上升而单步时延指标好看。后者更危险，因为监控面板上单步时延是达标的，只有把 batch 实际并发数与排队深度放在同一张图上才能看出问题。工程判断是：把缓存预算做成显式配额而非按需分配，在请求准入阶段就按分辨率分桶估算 $M_{\\text{cache}}$，拒绝那些会把 $B_{\\max}$ 压到阈值以下的请求进入高优先级队列，而不是等到运行时 OOM 再回滚。</p>\n<p>具体例子：同一张卡上，512×512 请求的缓存占用使 $B_{\\max}$ 维持在较高档位，而 1024×1024 请求的缓存占用把 $B_{\\max}$ 压到个位数；混合负载下若不做分辨率分桶，大请求会挤占小请求的并发空间，整体吞吐低于全部走全量重算的基线。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-41\">四十一 · 执行失败：分支破坏 kernel 规整性与 CUDA Graph 断裂</h3>\n<p>相似度判定与救援调度在数据流上引入 per-block 的条件分支：一部分 block 走缓存读取，一部分 block 走前向重算。这直接破坏了 kernel 的规整性——原本所有 block 执行同一条融合算子链，现在执行路径随 $s_i$ 逐 block 变化。CUDA Graph 捕获要求执行图在执行前完全确定，条件分支使图结构在捕获时不可知，若不做分段捕获，表现为捕获失败或重放时读到错误的缓存指针，单步时延收益被抵消甚至倒挂。</p>\n<p>分段捕获的思路是把单个 step 切成三段固定图：判定段（计算全部 $s_i$ 并生成复用掩码）、救援段（按掩码收集需重算的 block 索引，以固定形状的批处理执行重算）、汇聚段（残差修正与写回缓存、进入 scheduler）。三段各自是规整的，掩码作为数据在段间传递而非改变图结构。伪代码层面：</p>\n<div class=\"formula\">$$\\text{mask}_i=\\mathbb{1}[s_i\\le\\tau],\\quad \\text{idx}=\\text{nonzero}(\\text{mask}),\\quad h_i^{t}=\\text{mask}_i\\cdot\\text{Recompute}(i)+(1-\\text{mask}_i)\\cdot\\text{Cache}_i$$</div>\n<p>救援段按 idx 做 gather/scatter，其形状随救援 block 数变化，因此需要按最大救援数预分配缓冲并对不足部分做填充，否则动态形状同样会让图重捕获。代价是判定段本身要跑一遍全部 block 的键计算，这部分算力无法跳过；当救援率极低时，判定开销在单步时延中的占比上升，收益被摊薄。诊断执行失败的关键指标是图重捕获次数与重放错误计数：重捕获次数在稳态下应为零，任何非零都意味着有分支逃逸出了分段设计。</p>\n<p>具体例子：未分段捕获时，一个 batch 内不同请求的救援掩码不同，图在捕获阶段只能按首个请求的掩码固化，后续请求重放时读到错位的缓存槽，输出出现块级错位伪影；改为三段捕获后，掩码作为张量输入，同一张图服务全部请求，重捕获次数归零。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-42\">四十二 · 调度失败：批抖动、路由不均与尾延迟尖刺</h3>\n<p>批抖动来自救援率的请求间方差。连续批处理下，一个 batch 内各请求的救援 block 数不同，救援段的有效工作量随批次组成波动，单步时延随之抖动。当调度器按固定时间片切分时，高救援请求会拖长整个 batch 的 step 时间，低救援请求被无辜拖慢，表现为 p99 单步时延尖刺而 p50 平稳。诊断要看救援 block 数的分布而非均值：均值低但方差大，说明少数请求承担了绝大部分重算，这些请求就是尾延迟的来源。</p>\n<p>路由不均出现在多卡或多副本部署下。若请求按轮询分发而不考虑其分辨率与预估救援率，某些副本持续接收高救援请求，其队列深度与 step 时间双双上升，而其他副本空闲。这与缓存显存的分桶策略耦合：大分辨率请求的 $M_{\\text{cache}}$ 大、$B_{\\max}$ 小，若与低分辨率请求混在同一副本，副本的有效并发被拉低。工程做法是把预估救援率与分辨率作为路由键的一部分，做亲和性分发，并在副本间保留可迁移的溢出队列。</p>\n<p>尾延迟尖刺还有一个隐蔽来源：救援触发的时刻与批边界不对齐。若某请求在 step 中途触发大面积救援，其重算量超出该 step 的预算，调度器要么等待（拉长 step）要么拆分（引入额外同步），两者都在 p99 上留下尖刺。缓解手段是给单 step 的救援 block 数设上限，超出部分顺延到下一步，用轻微的质量让步换取时延可预测性；这个上限本身要作为 SLO 参数暴露，而不是硬编码。</p>\n<p>具体例子：一个混合分辨率负载中，1024×1024 请求占比两成但贡献了绝大部分救援 block 数，轮询路由下这些请求均匀散落各副本，每个副本都被拖出一条尾延迟长尾；改为按分辨率亲和路由后，大请求集中到缓存预算充裕的副本，小请求副本的 p99 回落到与 p50 接近的水平。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-43\">四十三 · 监控面：把三个失败域压到一张面板</h3>\n<p>监控要覆盖精度、显存、执行、调度四个域，且指标必须能互相归因。精度域看救援率的时序曲线与救援 block 深度的分布，前者暴露阈值失配，后者暴露分层阈值配置错误；显存域看 $M_{\\text{cache}}$ 实际占用、$B_{\\max}$ 实际并发与排队深度三者的联动，单看显存占用率会漏掉软塌陷；执行域看图重捕获次数、重放错误计数与判定段在单步时延中的占比；调度域看救援 block 数的 p50/p99 分位差与副本间的救援率方差。</p>\n<table class=\"mini\"><thead><tr><th>失败域</th><th>核心指标</th><th>判据</th><th>归因方向</th></tr></thead><tbody><tr><td>精度</td><td>救援率时序、救援深度分布</td><td>救援率贴地但质量降</td><td>阈值过松或分层失配</td></tr><tr><td>显存</td><td>缓存占用、实际并发、排队深度</td><td>单步时延达标但吞吐降</td><td>缓存挤占 batch 容量</td></tr><tr><td>执行</td><td>图重捕获次数、重放错误</td><td>稳态非零</td><td>分支逃逸分段设计</td></tr><tr><td>调度</td><td>救援 block 数 p99、副本救援率方差</td><td>p99 远高于 p50</td><td>路由不均或批组成失衡</td></tr></tbody></table>\n<p>面板设计的关键是把单步时延与救援率画在同一时间轴上：时延下降伴随救援率上升是正常收益，时延下降但救援率贴地且质量指标恶化就是漏救援；时延上升伴随救援率上升说明阈值过紧或批组成恶化。质量指标本身难以在线获取，工程上退而用代理指标——相邻 step latent 的余弦相似度均值、救援 block 输出的残差范数——作为漂移的早期信号，这些量在判定段已有中间结果，几乎零额外开销。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-44\">四十四 · 回滚路径：分级降级而非一刀切关闭</h3>\n<p>回滚不是把缓存算法整体关掉，而是分级降级，每一级对应一个失败域。第一级是阈值回滚：把 $\\tau$ 整体上调或按深度上调，用更多救援换质量，代价是单步时延收益收窄；这一级可在请求粒度生效，只对漂移信号强的请求收紧。第二级是缓存预算回滚：把 $M_{\\text{cache}}$ 配额下调、$B_{\\max}$ 相应回升，用吞吐换显存安全，适用于软塌陷场景。第三级是执行路径回滚：关闭分段捕获中的救援段动态形状，退化为固定救援数上限的规整图，牺牲部分救援精度换图稳定性。第四级才是整体关闭，回到全量重算基线。</p>\n<p>分级回滚的前提是每一级都有独立的开关与可观测的生效确认。工程判断上，回滚触发条件应绑定到具体指标而非人工判断：救援率贴地加漂移代理指标越界触发第一级，$B_{\\max}$ 低于准入阈值触发第二级，图重捕获次数非零触发第三级。回滚动作本身要记录版本与生效范围，否则在多副本部署下无法区分“已回滚的副本”与“未触发回滚的副本”，事后归因失效。</p>\n<p>具体例子：某副本在语义切换密集的负载下漂移代理指标连续越界，第一级回滚把该副本的 $\\tau$ 上调，救援率从贴地升到稀疏脉冲，单步时延收益从 20%–40% 收窄到较低区间，但输出质量恢复；与此同时其他副本维持原阈值，整体吞吐不受影响。这个例子说明回滚的粒度应落在副本与请求桶上，而不是全局配置——全局回滚会把未受影响的负载一并拖回基线，损失本可保留的收益。</p>\n<h3 id=\"alg-feature-cache-rescue-sec-45\">四十五 · 对照轴：三条改动路径的坐标系</h3>\n<p>把本算法放回同族算法的坐标系里，先要确定对照轴。扩散推理加速的同族手段可以沿两个正交维度切分：一是<strong>是否改变采样轨迹</strong>（步数与轨迹形状），二是<strong>是否改变单步内部的计算路径</strong>。步数蒸馏与一致性模型落在第一维的“改变”侧——它们重写从噪声到样本的映射，把多步压缩成少步，代价是必须重训练、且轨迹被固定，换分辨率或换调度器往往要重新蒸馏。固定间隔缓存落在第二维的“改变”侧但方式粗糙：按固定 step 周期复用整步或整块输出，不检测相似度，因此无法区分“语义平稳段”与“语义切换点”，在切换处直接复用即产生漂移。本算法同样落在第二维，但把复用粒度下沉到 block、把触发条件换成数据驱动的相似度判定，并配一条救援队列兜底。整流流直线采样器则属于第一维的“改变”侧但改动更轻，它重排采样路径而不压缩步数。三条路径的工程含义完全不同：第一维的手段省的是“步数乘子”，第二维的手段省的是“单步内的 block 乘子”，二者可以叠加，但叠加时收益不是相加而是相乘后受显存约束截断。</p>\n<p>决策的第一个判据因此不是“哪个更快”，而是“手上有没有重训练预算与轨迹稳定性要求”。有重训练预算、且服务形态固定（分辨率、步数、调度器不常变），步数蒸馏的收益上限最高；无重训练预算、或需要在线切换分辨率与采样器，则只能落在第二维，此时本算法与固定间隔缓存是直接竞品。第二个判据是语义切换的稀疏性：本算法的收益正比于被跳过的 block 比例，而跳过比例由相似度分布决定。语义切换稀疏（例如以背景与静态结构为主的生成、图生图的轻度编辑）时复用率高；语义切换密集（多主体交互、快速运动、文本强约束的复杂构图）时救援队列被频繁触发，分支开销上升而收益下降。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-46\">四十六 · 决策表：五类场景的选型与适用条件</h3>\n<p>下表把同族算法按“改动对象 / 是否重训练 / 主要代价 / 适用条件”四列对齐，供工程选型时逐行比对。表中不给出未在材料中出现的定量阈值，只标注定性边界。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>算法</th><th>改动对象</th><th>是否重训练</th><th>主要代价</th><th>适用条件</th></tr>\n</thead>\n<tbody>\n<tr><td>本算法（特征缓存 + 动态救援）</td><td>单步内 block 计算路径</td><td>否</td><td>缓存显存、分支破坏 kernel 规整性</td><td>相邻 step 相似度高、语义切换稀疏；显存预算可容纳 block 级缓存</td></tr>\n<tr><td>固定间隔缓存</td><td>单步内整步/整块复用</td><td>否</td><td>切换处漂移、画质与一致性双损</td><td>语义极平稳、对画质退化容忍度高；实现最简单</td></tr>\n<tr><td>步数蒸馏</td><td>采样轨迹与步数</td><td>是</td><td>重训练成本、轨迹锁定</td><td>服务形态固定、有训练预算、追求步数乘子收益</td></tr>\n<tr><td>一致性模型</td><td>采样轨迹（少步映射）</td><td>是</td><td>重训练成本、少步下多样性受限</td><td>低步数硬 SLO、可接受轨迹重写</td></tr>\n<tr><td>整流流直线采样器</td><td>采样路径形状</td><td>否（改调度）</td><td>路径重排带来的数值稳定性调参</td><td>需要在不重训练前提下改善少步质量</td></tr>\n</tbody>\n</table>\n<p>读表要点有三。其一，本算法与固定间隔缓存共享“不重训练”这一优势，但前者用相似度判定换来了救援能力，代价是分支与缓存管理复杂度；若团队连 CUDA Graph 分段捕获都不打算做，固定间隔缓存反而是更稳的工程选择，因为它的分支结构是静态的、可被完整捕获。其二，本算法与步数蒸馏不是替代关系而是叠加关系：先用蒸馏把步数压到少步，再在剩余步内做 block 级复用，两级乘子相乘；但少步之后相邻 step 的相似度分布会变——步长变大，相似度整体下降，复用率随之下降，因此叠加时阈值必须重新标定，不能沿用多步配置。其三，整流流直线采样器改变的是路径形状而非计算量，它与本算法叠加时，路径变直意味着相邻 step 的隐状态变化更接近线性，相似度判定更容易稳定命中，属于正向耦合。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-47\">四十七 · 选型判据的形式化：收益与约束的不等式</h3>\n<p>把选型写成可计算的不等式，比凭直觉拍板更可靠。设单步全量计算时间为 $T_{\\text{full}}=\\sum_\\ell T_\\ell$，复用率为 $\\rho$（被跳过 block 的比例），则本算法的单步时间近似为</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx (1-\\rho)\\,T_{\\text{full}} + T_{\\text{cache}} + T_{\\text{branch}}$$</div>\n<p>其中 $T_{\\text{cache}}$ 是缓存读写开销，$T_{\\text{branch}}$ 是相似度判定与救援调度的分支开销。材料给出的单步时延降幅 20%–40% 对应的是 $\\rho$ 落在中高区间、且 $T_{\\text{cache}}+T_{\\text{branch}}$ 被 CUDA Graph 分段捕获压住的情形。若分支未被捕获，$T_{\\text{branch}}$ 会以 kernel 启动与重放错误的形式放大，把降幅吃掉。选型的第一个不等式是收益条件：$(1-\\rho)T_{\\text{full}}+T_{\\text{cache}}+T_{\\text{branch}} &lt; T_{\\text{full}}$，即 $\\rho T_{\\text{full}} &gt; T_{\\text{cache}}+T_{\\text{branch}}$。当 $\\rho$ 因语义切换密集而走低时，该不等式右侧不变而左侧缩水，算法自动失效——这正是失败模式中“阈值过松漏救援”与“阈值过紧救援过频”两侧夹击的数学形态。</p>\n<p>第二个不等式是显存约束。设缓存占用为 $M_{\\text{cache}}$（与 block 数、隐维、分辨率、批大小成正比），激活与 KV 占用为 $M_{\\text{act}}$，则批大小必须满足 $B\\cdot(M_{\\text{cache}}+M_{\\text{act}}) \\le M_{\\text{budget}}$。高分辨率大 DiT 下 $M_{\\text{cache}}$ 随分辨率平方增长，与 KV/激活争抢预算，$B$ 被压小；而吞吐正比于 $B\\cdot\\rho$ 带来的单步节省，于是出现“单步更快但吞吐不升反降”的悖论区间。工程判断因此是：先按显存预算反解出可承受的 $B$，再看该 $B$ 下 $\\rho$ 是否仍能撑起收益不等式；两者同时成立才选本算法，否则退到固定间隔缓存（缓存粒度更粗、$M_{\\text{cache}}$ 更小）或直接不做块级复用。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-48\">四十八 · 具体例子：一次选型推演</h3>\n<p>设某服务同时承接两类请求：一类是高分辨率、多主体的复杂构图，另一类是中等分辨率的轻度编辑与背景延展。两类请求按分辨率与步数分桶，共享同一套 DiT 权重。对第一类，语义切换密集，逐 block 相似度在主体边界处频繁跌破阈值，救援队列被反复触发，$\\rho$ 低而 $T_{\\text{branch}}$ 高，收益不等式难以成立；同时高分辨率使 $M_{\\text{cache}}$ 膨胀，$B$ 被压到很小，吞吐侧无利可图。对第二类，语义平稳段长，$\\rho$ 高，救援只在少数切换点触发，单步时延降幅可落在材料给出的 20%–40% 区间内，且中等分辨率下 $M_{\\text{cache}}$ 尚可与激活共存。</p>\n<p>推演结论不是“全量启用”或“全量禁用”，而是按桶分流：第二类桶启用本算法并配 CUDA Graph 分段捕获；第一类桶退回固定间隔缓存或干脆全量计算，把省下的显存预算让给第二类桶的批大小。分流本身有代价——两套执行路径意味着两套图捕获、两套显存规划，调度器要按桶打标。若桶边界不稳定（请求在两类之间漂移），分流收益会被路径切换开销侵蚀，此时更稳的做法是单一固定间隔缓存路径加保守阈值，牺牲部分收益换确定性。这个例子说明：本算法的适用条件不是模型级的，而是<strong>请求桶级</strong>的，选型必须落到桶上而非落到服务上。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-49\">四十九 · 与量化、注意力的交叉约束</h3>\n<p>选型还要看同模块其他条目所讲的量化与注意力路径是否已经改动了单步的数值形态。当 DiT 采用 NVFP4 或 FP8 混合精度、注意力走异步 FA3 时，block 输出的数值噪声底被抬高，余弦相似度的分布在阈值附近变得更抖：低精度下同一语义状态的两次前向本就存在量化抖动，$s_i$ 的方差增大，阈值 $\\tau$ 必须相应上调以避免误判复用，但上调又会漏掉真实的语义切换救援。这是一个双向夹逼：量化越激进，本算法的判定裕度越窄。工程上的处理是把相似度判定放在高精度侧——用缓存键（通常是 block 输入的归一化投影）而非低精度输出本身做比较，让判定不受输出量化噪声污染；代价是多一次轻量投影计算，计入 $T_{\\text{branch}}$。</p>\n<p>注意力侧的交叉约束在显存：异步 FA3 与 KV 缓存本就占用激活预算，本算法的 block 级缓存再叠上去，三者争抢同一块 HBM。若注意力已采用分块或重计算策略压低激活峰值，本算法的缓存可以借用这部分腾出的空间；反之若注意力为了吞吐保留了完整 KV，缓存就只能挤占批大小。这解释了为什么本算法的部署配方在材料中未给出固定硬件档位——它的可行域由同服务内其他算法的显存占用共同决定，是一个联合规划问题而非单算法调参问题。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-50\">五十 · 适用条件的硬边界与选型收口</h3>\n<p>把适用条件写成硬边界，便于在容量规划阶段直接判定。第一条硬边界是语义切换稀疏性：若请求桶内语义切换点的密度高到使 $\\rho$ 无法撑起收益不等式，本算法不适用，无论阈值怎么调。第二条是显存：若 $M_{\\text{cache}}$ 在高分辨率下使 $B$ 降到吞吐不可接受的水平，本算法不适用，除非能与注意力侧的激活压缩联合腾挪。第三条是执行图规整性：若团队无法承担 CUDA Graph 分段捕获的改造成本，分支开销会抵消收益，此时固定间隔缓存是更优的工程判断。第四条是叠加顺序：与步数蒸馏叠加时必须重新标定阈值，因为少步后相似度分布整体下移；与整流流直线采样器叠加时判定更稳，可适当放宽 $\\tau$ 以换取更高 $\\rho$。</p>\n<p>收口到一句工程判断：本算法的选型不是“比固定间隔缓存更聪明所以选它”，而是“在无重训练预算、语义切换稀疏、显存可容纳 block 级缓存、且愿意为分支做图捕获改造”这四个条件同时成立时才选它；任一条件不成立，退回固定间隔缓存或全量计算是更稳的决策。选型的最终落点不在算法优劣，而在请求桶的相似度分布与显存预算的联合可行域——这也是把本算法与同族其他算法放在同一张决策表上比对的意义。</p>\n\n<h3 id=\"alg-feature-cache-rescue-sec-51\">五十一 · 与固定间隔缓存、步数蒸馏的选型边界</h3>\n<p>同族算法里最容易被误用的是把本方案当成“固定间隔缓存”的升级版。两者代价结构完全不同：固定间隔缓存按固定 step 周期复用，判定成本为零、kernel 完全规整，但它在语义切换处没有任何检测手段，漂移只能靠调大间隔来赌；本方案把判定下沉到 block 粒度，用 $$s_i=\\cos(\\mathbf{k}_i^{t},\\mathbf{k}_i^{t-1})$$ 逐 block 决策，代价是每个 block 多一次相似度计算与一次分支。选型判据是语义切换的稀疏度：采样轨迹中切换点密集（如高引导尺度、少步数、强条件编辑）时，逐 block 判定的收益被分支开销吃掉，固定间隔反而更稳；切换稀疏、步数多、分辨率适中时，逐 block 判定才划算。步数蒸馏与一致性模型则是另一条路——它们改采样轨迹与步数，需要重训练；本方案不动轨迹，只改单步内计算路径，因此可与蒸馏叠加，但不能用来替代蒸馏去追极低步数。</p>\n<p>失效条件集中在阈值与执行两个环节。阈值 τ 过松，语义切换处的 block 相似度仍越线，缓存输出直接汇入 scheduler，表现为画面局部漂移与跨 step 一致性下降，且这种退化不会在单步时延上暴露，只能靠离线画质比对发现；τ 过紧则救援队列膨胀，单步退化为近似全量重算，收益归零。执行侧的硬约束是分支破坏 kernel 规整性，必须做 CUDA Graph 分段捕获，把“判定—复用段”与“救援重算段”拆成可重放的图段；未分段捕获时会出现捕获失败或重放错误，单步时延收益被直接抵消。系统代价还有一笔显存账：缓存按 block 输出常驻，高分辨率大 DiT 下与 KV/激活争抢预算，batch 容量被迫下调，吞吐可能不升反降。</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>优先选择</th><th>关键代价</th></tr></thead><tbody><tr><td>语义切换稀疏、步数多、分辨率适中</td><td>逐 block 相似度复用 + 动态救援</td><td>判定分支、CUDA Graph 分段捕获</td></tr><tr><td>切换密集、引导尺度高、步数少</td><td>固定间隔缓存或全量重算</td><td>画质漂移或算力浪费</td></tr><tr><td>目标极低步数、可重训练</td><td>步数蒸馏 / 一致性模型</td><td>改变采样轨迹，需训练投入</td></tr><tr><td>显存紧张、batch 优先</td><td>缩小缓存粒度或放弃缓存</td><td>单步时延收益 20%–40% 让位于吞吐</td></tr></tbody></table>\n<p>工程判断落在预算分配顺序上：先按分辨率与步数分桶确定缓存显存上限，再反推可支撑的 batch，最后才调 τ。若显存预算无法同时容纳缓存与目标 batch，本方案的 20%–40% 单步时延收益不足以补偿吞吐损失，应退回固定间隔或全量路径；只有当切换稀疏度经离线统计确认、且 CUDA Graph 分段捕获已验证可重放时，逐 block 判定加救援队列才是正确选型。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 扩散服务化与 SLO 调度</td></tr><tr><td>解决什么</td><td>扩散多步采样中相邻 step 的 DiT block 输出高度相似，全量重算浪费算力；但盲目缓存会在语义切换处引入漂移…</td></tr><tr><td>一句话机制</td><td>按 block 输出与上一步的相似度决定复用，相似度高则跳过该 block 计算直接取缓存；检测到局部差异超阈时触发动…</td></tr><tr><td>代价与失效</td><td>相似度判定与救援调度引入分支，破坏 kernel 规整性，需 CUDA Graph 分段捕获；缓存占用显存，高分辨率大 DiT 下与 KV…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-feature-cache-rescue · 共 8 个片段</p>\n";break;}}})();
